"""Explicit Hamiltonian ball packings of the four-ball, numerical implementation for the Epoch AI interface.

solution(k, epsilon), for an integer k >= 10 and 0 < epsilon < 1, returns the source of a Python module that
defines Hamiltonian(Q, P, t) (PyTorch, float64; Q, P of shape (N, 2); returns shape (N,)). The time-1 flow of
this Hamiltonian is designed to map the k closed unit balls centred at (3i - 3, 0, 0, 0), i = 1..k, into the
ball B(R) about the origin with k / R^4 > 1 - epsilon.

Constructions (the elementary constructions of Paper III of the accompanying release):
  toric    lattice-toric layouts for 10 <= k <= 100000: k unit simplices in the moment triangle Delta(A),
           moved into place by a composition of explicit Hamiltonian segments (keyhole, shears, toric moves).
           Square k = n^2: every epsilon > 0.002. Other k: epsilon above the static deficit 1 - k / A^2 of the best
           available layout plus about 0.002; eps_min(k) returns the bound.
  k10_sw2  k = 10, sheared-window configuration in B(19/6 L(epsilon)) (density 360/361 in the limit),
           every epsilon >= 0.005.
Inputs outside the covered range raise NotImplementedError and report the smallest covered epsilon.

Status: the configurations and the motions are explicit, but that the time-1 flow packs is supported by numerical
integration (fixed-step RK4 at N and 2N steps, see README.md and check.py), not by a proof.

Helpers: recommended_steps(k, epsilon) (RK4 steps N; the check is expected to pass at N and 2N), eps_min(k),
coverage(k), describe(k, epsilon). The module-level strings SRC, PLAN_SRC and EXT_SRC hold generated source code
of the building blocks; they are executed as they are.
"""
SRC = '"""Building block: lattice-toric packing by explicit Hamiltonian segments (generated source)."""\nimport math\nimport torch\n\nF64 = torch.float64\nLAM = math.sqrt(math.pi)\n\n\ndef sstep(u):\n    """Flat smooth step (scalar or tensor) and its derivative."""\n    u = torch.as_tensor(u, dtype=F64).clamp(0, 1)\n    e1 = torch.where(u > 0, torch.exp(-1 / u.clamp_min(1e-300)), torch.zeros_like(u))\n    e2 = torch.where(u < 1, torch.exp(-1 / (1 - u).clamp_min(1e-300)), torch.zeros_like(u))\n    d1 = torch.where(u > 0, e1 / u.clamp_min(1e-300) ** 2, torch.zeros_like(u))\n    d2 = torch.where(u < 1, -e2 / (1 - u).clamp_min(1e-300) ** 2, torch.zeros_like(u))\n    return e1 / (e1 + e2), (d1 * e2 - e1 * d2) / (e1 + e2) ** 2\n\n\ndef tclock(u, kind):\n    """Trigonometric-polynomial clocks: \'sin2\' S\' = 1 - cos 2 pi u (vanishing to order 2 at the ends); \'sin4\' S\' = (8/3) sin^4 pi u (order 4).\n    All derivatives are moderate, unlike sstep, whose exp(-1/u) transition has very large higher derivatives."""\n    u = float(min(max(u, 0.0), 1.0))\n    a = 2 * math.pi * u\n    if kind == \'sin2\':\n        return u - math.sin(a) / (2 * math.pi), 1 - math.cos(a)\n    if kind == \'sin4\':\n        return (u - 2 * math.sin(a) / (3 * math.pi) + math.sin(2 * a) / (12 * math.pi),\n                1 - 4 * math.cos(a) / 3 + math.cos(2 * a) / 3)\n    raise ValueError(kind)\n\n\n_GL_X, _GL_W = None, None\n\n\ndef pclock(u, tau=None, nodes=64):\n    """Clock S(u), S\'(u). tau=None: flat step (default). Given tau: plateau clock S\' proportional to sstep(u/tau) sstep((1-u)/tau).\n    With tau=0.15 the transitions are so steep that the Simpson quadrature error grows about 100-fold, so this is not the default."""\n    if tau is None:\n        S, dS = sstep(torch.tensor(float(min(max(u, 0.0), 1.0)), dtype=F64))\n        return float(S), float(dS)\n    global _GL_X, _GL_W\n    if _GL_X is None:\n        import numpy as _np\n        xg, wg = _np.polynomial.legendre.leggauss(nodes)\n        _GL_X, _GL_W = torch.tensor(xg, dtype=F64), torch.tensor(wg, dtype=F64)\n\n    def b(v):\n        return sstep(v / tau)[0] * sstep((1 - v) / tau)[0]\n\n    def integ(a, c):\n        tot = 0.0\n        for j in range(4):\n            a0, a1 = a + (c - a) * j / 4, a + (c - a) * (j + 1) / 4\n            tot = tot + 0.5 * (a1 - a0) * (_GL_W * b(a0 + 0.5 * (a1 - a0) * (_GL_X + 1))).sum()\n        return tot\n    u = float(min(max(u, 0.0), 1.0))\n    Z = integ(0.0, 1.0)\n    return float(integ(0.0, u) / Z), float(b(torch.tensor(u, dtype=F64)) / Z)\n\n\ndef window(z, half, trans):\n    """Smooth window: 1 for |z| <= half, 0 for |z| >= half + trans."""\n    return 1 - sstep((z.abs() - half) / trans)[0]\n\n\nclass Toric:\n    def __init__(self, n, g0=0.02, kh=(0.015, 9.0, 3e-3, 0.1, 1e-2), kh_out=(0.0150, 9.3e-7),\n                 x0=4e-7, kappa=1 / (2 * math.pi), s0=0.005, band=4.4,\n                 weights=(1.1, 1.1, 0.35, 1.3, 1.0, 1.35, 1.15, 1.65), Lam_s=7.0,\n                 schedule=\'lin\', logit_d=2e-3, clock=\'sstep\', s6_tw=0.6):\n        self.n, self.k = n, n * n\n        self.clock = clock\n        self.s6_tw = s6_tw\n        # scale-invariant keyhole: (delta_rel, c_in, xc, CT, XG)\n        self.drel, self.cin, self.xc, self.CT, self.XG = kh\n        self.w_kh = self.drel / self.cin\n        # measured keyhole data (units a = 1): effective delta and hole\n        self.d_eff, self.hole = kh_out\n        wsum = sum(weights)\n        self.tb = [0.0]\n        for wgt in weights:\n            self.tb.append(self.tb[-1] + wgt / wsum)\n        self.x0, self.kappa, self.s0 = x0, kappa, s0\n        self.Lam_s = Lam_s\n        self.schedule, self.logit_d = schedule, logit_d\n        self.rho1 = math.sqrt(x0 / math.pi)\n        self.g0 = g0\n        self.cg = 1 + 2 * self.d_eff + 3 * g0 - 2 * self.hole\n        self.R = math.sqrt(n * self.cg)\n        self.density = 1 / self.cg ** 2\n        k = self.k\n        self.X = [3.0 * i for i in range(k)]\n        self.v = [band * (i - (k - 1) / 2) for i in range(k)]\n        self.band = band\n        # triangles and placement: upper triangles (i,j), i+j<=n-1; lower triangles (i,j), i+j<=n-2\n        pieces = []\n        for i in range(n):\n            for j in range(n - i):\n                b = (i * self.cg + g0 - self.hole, j * self.cg + g0 - self.hole)\n                pieces.append((\'up\', b, ((i * self.cg, j * self.cg), \'up\')))\n        for i in range(n - 1):\n            for j in range(n - 1 - i):\n                bp = ((i + 1) * self.cg - g0 + self.hole, (j + 1) * self.cg - g0 + self.hole)\n                pieces.append((\'down\', bp, (((i + 1) * self.cg, (j + 1) * self.cg), \'down\')))\n        assert len(pieces) == k\n        self.pieces = pieces\n        # the three half-planes (a.x <= c) of each target triangle, for the smooth indicator of S6\n        self.tri = []\n        for kind, _, (corner, _) in pieces:\n            cx, cy = corner\n            if kind == \'up\':\n                self.tri.append([((-1, 0), -(cx + g0)), ((0, -1), -(cy + g0)), ((1, 1), cx + cy + self.cg - g0)])\n            else:\n                self.tri.append([((1, 0), cx - g0), ((0, 1), cy - g0), ((-1, -1), -(cx + cy - self.cg + g0))])\n\n    def clk(self, u, m):\n        kind = self.clock if isinstance(self.clock, str) else self.clock[m]\n        return pclock(u) if kind == \'sstep\' else tclock(u, kind)\n\n    def sched(self, sig):\n        """Wrapping parameter s(sigma), sigma in [0,1], s(0)=1, s(1)=s0; returns (s, ds/dsigma)."""\n        s0 = self.s0\n        if self.schedule == \'lin\':\n            return 1 - (1 - s0) * sig, -(1 - s0)\n        if self.schedule == \'exp\':\n            Lm = self.Lam_s; e = math.exp(Lm * sig); D = math.exp(Lm) - 1\n            return 1 - (1 - s0) * (e - 1) / D, -(1 - s0) * Lm * e / D\n        # logit: l = log(s / (1 - s + d1)) is linear in sigma, from l(1) to l(s0)\n        d1 = self.logit_d\n        l0, l1 = math.log(1 / d1), math.log(s0 / (1 - s0 + d1))\n        l = l0 + (l1 - l0) * sig\n        E = math.exp(l)                       # s = E (1 - s + d1)  =>  s = E (1 + d1) / (1 + E)\n        s = E * (1 + d1) / (1 + E)\n        dsdl = (1 + d1) * E / (1 + E) ** 2\n        return s, dsdl * (l1 - l0)\n\n    # ---------- planar primitives (unit-area coordinate w, shape (N,2)) ----------\n    def kh1(self, w):\n        x = math.pi * w.square().sum(1)\n        phi = torch.atan2(w[:, 1], w[:, 0]) / (2 * math.pi)\n        F = x ** 3 / (x ** 3 + self.xc ** 3)\n        S = self.drel * (sstep((phi / self.w_kh + 1) / 2)[0] - 0.5 - phi)\n        cut = 1 - sstep((x - 1.3) / 0.5)[0]\n        return -x * F * S * cut\n\n    def kh2(self, w):\n        x = math.pi * w.square().sum(1)\n        return -self.CT * torch.exp(-x / self.XG) * w[:, 1]\n\n    def geom(self, s):\n        s = torch.as_tensor(s, dtype=F64)\n        rho2 = self.x0 / math.pi + self.kappa ** 2 * (1 / s - 1) ** 2\n        rho = rho2.sqrt(); rho_p = -self.kappa ** 2 * (1 / s - 1) / s ** 2 / rho\n        phi = math.pi - math.pi * s\n        return s, rho, rho_p, phi, -math.pi, rho - self.rho1, rho_p\n\n    def wrap_K(self, w, s):\n        """Generator K_s of d/ds (unit-area coordinates)."""\n        s, rho, rho_p, phi, phi_p, c, c_p = self.geom(s)\n        dq, dp = w[:, 0] - c, w[:, 1]\n        x = self.x0 + math.pi * s * (dq ** 2 + dp ** 2 - rho ** 2)\n        base = phi - math.pi * (1 - s)\n        ang = torch.remainder(torch.atan2(dp, dq) - base, 2 * math.pi) + base\n        y = (ang - phi) / (2 * math.pi * s)\n        Hpol = 2 * math.pi * s * rho * rho_p * y - (x - self.x0) * y / s - phi_p * (x - self.x0) / (2 * math.pi * s)\n        return c_p * w[:, 1] + Hpol\n\n    def Binv(self, w, s=None):\n        """Inverse of B_s (unit-area coordinates -> (x, y)), default s = s0; the branch cut is opposite the sector."""\n        s, rho, _, phi, _, c, _ = self.geom(self.s0 if s is None else s)\n        dq, dp = w[:, 0] - c, w[:, 1]\n        x = self.x0 + math.pi * s * (dq ** 2 + dp ** 2 - rho ** 2)\n        base = phi - math.pi * (1 - s)\n        ang = torch.remainder(torch.atan2(dp, dq) - base, 2 * math.pi) + base\n        return x, (ang - phi) / (2 * math.pi * s)\n\n    def B(self, x, y, s=None):\n        s, rho, _, phi, _, c, _ = self.geom(self.s0 if s is None else s)\n        r = (rho ** 2 + (x - self.x0) / (math.pi * s)).sqrt(); th = 2 * math.pi * s * y + phi\n        return torch.stack([c + r * th.cos(), r * th.sin()], -1)\n\n    # ---------- Hamiltonian of each time segment (real coordinates y (N,4); returns (N,)) ----------\n    def seg_H(self, m, y, u):\n        q1, q2, p1, p2 = y.unbind(1)\n        z2 = torch.stack([q2, p2], 1) / LAM\n        k = self.k\n        S, dS = self.clk(u, m)\n        L2 = LAM ** 2\n        if m == 0:      # vertical kick\n            H = 0\n            for i in range(k):\n                H = H + (-self.v[i]) * (q1 - self.X[i]) * window(q1 - self.X[i], 1.2, 0.5)\n            return H\n        if m in (1, 2):  # keyhole\n            prim = self.kh1 if m == 1 else self.kh2\n            H = L2 * prim(z2)\n            for i in range(k):\n                z1 = torch.stack([q1 - self.X[i], p1 - self.v[i]], 1) / LAM\n                H = H + L2 * prim(z1) * window(p1 - self.v[i], self.band / 2 - 0.4, 0.2)\n            return H\n        if m in (3, 7):  # wrapping: S3 backwards (s: 1 -> s0), S7 forwards (s0 -> 1)\n            # 1-s grows exponentially in sigma: near s = 1 the relative growth rate of the inner radius is at most Lam_s\n            sig = float(S) if m == 3 else 1 - float(S)      # sigma: 0 means s=1, 1 means s=s0\n            s, dsds = self.sched(sig)\n            sdot = dsds if m == 3 else -dsds\n            H = L2 * self.wrap_K(z2, s)\n            if m == 3:\n                for i in range(k):\n                    z1 = torch.stack([q1 - self.X[i], p1 - self.v[i]], 1) / LAM\n                    H = H + L2 * self.wrap_K(z1, s) * window(p1 - self.v[i], self.band / 2 - 0.4, 0.2)\n            else:\n                H = H + L2 * self.wrap_K(torch.stack([q1, p1], 1) / LAM, s)\n            return sdot * H\n        if m == 4:      # z1: lower triangles turn by pi about their centre; z2: full linear transport (upper: translate by b2; lower: turn by pi about (b2\'/2,1/2))\n            x2, yy2 = self.Binv(z2)\n            H = 0\n            for i in range(k):\n                kind, b, _ = self.pieces[i]\n                if kind == \'up\':\n                    G = b[1] * yy2\n                else:\n                    x1, yy1 = self.Binv(torch.stack([q1 - self.X[i], p1 - self.v[i]], 1) / LAM)\n                    G = (math.pi / 2) * ((x1 - 0.5) ** 2 + (yy1 - 0.5) ** 2 + (x2 - b[1] / 2) ** 2 + (yy2 - 0.5) ** 2)\n                H = H + L2 * G * window(p1 - self.v[i], self.band / 2 - 0.4, 0.2)\n            return H\n        if m == 5:      # horizontal translation\n            # composition rule: the translation T_a(t) (a = -X_i S(u)) runs together with the x-translation in the B coordinate that moves with the chart centre;\n            # generator = translation generator + G o T_a(t)^{-1}, G = d1 * y1 (B coordinate). At the end it is exactly (0, v_i) + lam B(xi + d1 e_x).\n            Su = self.clk(u, m)[0]\n            H = 0\n            for i in range(k):\n                kind, b, _ = self.pieces[i]\n                d1 = b[0] if kind == \'up\' else b[0] - 1.0     # lower triangles were flipped about x1=0.5 in S4\n                _, yy1 = self.Binv(torch.stack([q1 - self.X[i] * (1 - Su), p1 - self.v[i]], 1) / LAM)\n                H = H + (-self.X[i] * (p1 - self.v[i]) + L2 * d1 * yy1) * window(p1 - self.v[i], self.band / 2 - 0.4, 0.2)\n            return H\n        if m == 6:      # remove the vertical offset\n            s, rho, _, _, _, c, _ = self.geom(self.s0)\n            xh1 = self.x0 + math.pi * s * ((c - q1 / LAM) ** 2 - rho ** 2)\n            x2, _ = self.Binv(z2)\n            H = 0\n            for i in range(k):\n                W = 1\n                # the gap between neighbouring pieces in a.x (not normalised) is always 2 g0 (axial and diagonal edges alike):\n                # the transition band sits in the middle of the gap, width tw*g0, leaving (1 - tw/2) g0 on each side.\n                tw = self.s6_tw\n                for (a1, a2), cc in self.tri[i]:\n                    W = W * (1 - sstep((a1 * xh1 + a2 * x2 - cc - (1 - tw / 2) * self.g0) / (tw * self.g0))[0])\n                H = H + self.v[i] * q1 * W\n            return H\n        raise ValueError(m)\n\n    def H(self, Q, P, t):\n        y = torch.cat([Q, P], 1)\n        t = float(t)\n        m = 0\n        while m < 7 and t >= self.tb[m + 1]:\n            m += 1\n        L = self.tb[m + 1] - self.tb[m]\n        u = (t - self.tb[m]) / L\n        _, dS = self.clk(u, m)\n        return dS / L * self.seg_H(m, y, u)\n\n\ndef field(T, y, t):\n    y = y.detach().requires_grad_(True)\n    h = T.H(y[:, :2], y[:, 2:], t)\n    g, = torch.autograd.grad(h.sum(), y)\n    return torch.cat([g[:, 2:], -g[:, :2]], 1)\n\n\ndef rk4(T, y, N, t0=0.0, t1=1.0, record=None):\n    h = (t1 - t0) / N\n    for n in range(N):\n        t = t0 + n * h\n        k1 = field(T, y, t); k2 = field(T, y + h / 2 * k1, t + h / 2)\n        k3 = field(T, y + h / 2 * k2, t + h / 2); k4 = field(T, y + h * k3, t + h)\n        y = (y + h / 6 * (k1 + 2 * k2 + 2 * k3 + k4)).detach()\n        if record is not None:\n            for b in T.tb[1:]:\n                if t < b <= t + h + 1e-15:\n                    record.append(y.clone())\n    return y\n\n\n# ---- toric_general.py ----\n"""generalised toric pipeline (subclass of toric4d.Toric).\n\nPieces = unit simplices with AXIS-LEGGED images  x_j = b_j + sigma_j * x_src_j  (sigma in {+1,-1}^2),\ni.e. per-factor rotation by pi in strip coordinates; this covers the 8 toric items of the A=3.3 B1 config\nafter re-tiling the trapezoids T+ = {s>=0.3, mu2<=1} and T- = {s<=-0.3, mu1<=1}.\nBalls not listed in `pieces` are PARKED: no kick, every stage either ignores them (p1 / q1 windows) or acts\non them by an exact round trip (z2 keyhole is the only net change).\n\nPlacement (config units A, scale lam = 1 + 2 d_eff + 3 g0 - 2 hole):\n  b_j = lam * C_j + sigma_j * (g0 - hole)     (C = config corner of the simplex legs)\nso each piece keeps gap g0 to its own config cell on all three sides; R^2 = A * lam - g0 for the toric part.\n"""\nimport math\nimport torch\n\n# A = 3.3 layout (config corner, signs); see k10_window.md section 2\nLAYOUT_K10 = [((1.3, 0.0), (1, 1)), ((2.3, 0.0), (1, 1)), ((0.0, 1.3), (1, 1)), ((0.0, 2.3), (1, 1)),\n              ((2.3, 1.0), (-1, -1)), ((1.0, 2.3), (-1, -1)), ((1.3, 0.0), (-1, 1)), ((0.0, 1.3), (1, -1))]\n\n\nclass ToricGeneral(Toric):\n    def __init__(self, k, layout, toric_balls, A=3.3, g0=5e-4, band=4.4, v0=None, q1_cut=10.0, **kw):\n        super().__init__(1, g0=g0, band=band, **kw)     # n=1 dummy; everything below is overwritten\n        self.k, self.A = k, A\n        self.toric_balls = list(toric_balls)\n        assert len(layout) == len(self.toric_balls)\n        lam = 1 + 2 * self.d_eff + 3 * g0 - 2 * self.hole\n        self.lam = lam\n        self.R = math.sqrt(A * lam - g0)\n        self.X = [3.0 * i for i in range(k)]\n        # toric balls get positive kicks band*(j+1); parked balls keep v = 0 (p1 in (-1,1))\n        self.v = [0.0] * k\n        for j, i in enumerate(self.toric_balls):\n            self.v[i] = band * (j + 1) if v0 is None else v0 + band * j\n        self.q1_cut = q1_cut\n        self.pieces, self.tri = {}, {}\n        for (C, sg), i in zip(layout, self.toric_balls):\n            b = tuple(lam * C[j] + sg[j] * (g0 - self.hole) for j in range(2))\n            self.pieces[i] = (sg, b)\n            Cl = (lam * C[0], lam * C[1])\n            self.tri[i] = [((-sg[0], 0), -sg[0] * Cl[0] - g0), ((0, -sg[1]), -sg[1] * Cl[1] - g0),\n                           ((sg[0], sg[1]), sg[0] * Cl[0] + sg[1] * Cl[1] + lam - g0)]\n\n    def bwin(self, p1, i):\n        return window(p1 - self.v[i], self.band / 2 - 0.4, 0.2)\n\n    def seg_H(self, m, y, u):\n        q1, q2, p1, p2 = y.unbind(1)\n        z2 = torch.stack([q2, p2], 1) / LAM\n        S, dS = self.clk(u, m)\n        L2 = LAM ** 2\n        TB = self.toric_balls\n        if m == 0:\n            H = 0\n            for i in TB:\n                H = H + (-self.v[i]) * (q1 - self.X[i]) * window(q1 - self.X[i], 1.2, 0.5)\n            return H\n        if m in (1, 2):\n            prim = self.kh1 if m == 1 else self.kh2\n            H = L2 * prim(z2)\n            for i in TB:\n                z1 = torch.stack([q1 - self.X[i], p1 - self.v[i]], 1) / LAM\n                H = H + L2 * prim(z1) * self.bwin(p1, i)\n            return H\n        if m in (3, 7):\n            sig = float(S) if m == 3 else 1 - float(S)\n            s, dsds = self.sched(sig)\n            sdot = dsds if m == 3 else -dsds\n            H = L2 * self.wrap_K(z2, s)\n            if m == 3:\n                for i in TB:\n                    z1 = torch.stack([q1 - self.X[i], p1 - self.v[i]], 1) / LAM\n                    H = H + L2 * self.wrap_K(z1, s) * self.bwin(p1, i)\n            else:\n                qw = 1 - sstep((q1 - self.q1_cut) / 3.0)[0]\n                H = H + L2 * self.wrap_K(torch.stack([q1, p1], 1) / LAM, s) * qw\n            return sdot * H\n        if m == 4:\n            x2, yy2 = self.Binv(z2)\n            H = 0\n            for i in TB:\n                sg, b = self.pieces[i]\n                G = 0\n                if sg[0] < 0:\n                    x1, yy1 = self.Binv(torch.stack([q1 - self.X[i], p1 - self.v[i]], 1) / LAM)\n                    G = G + (math.pi / 2) * ((x1 - 0.5) ** 2 + (yy1 - 0.5) ** 2)\n                if sg[1] > 0:\n                    G = G + b[1] * yy2\n                else:\n                    G = G + (math.pi / 2) * ((x2 - b[1] / 2) ** 2 + (yy2 - 0.5) ** 2)\n                H = H + L2 * G * self.bwin(p1, i)\n            return H\n        if m == 5:\n            Su = self.clk(u, m)[0]\n            H = 0\n            for i in TB:\n                sg, b = self.pieces[i]\n                d1 = b[0] if sg[0] > 0 else b[0] - 1.0\n                _, yy1 = self.Binv(torch.stack([q1 - self.X[i] * (1 - Su), p1 - self.v[i]], 1) / LAM)\n                H = H + (-self.X[i] * (p1 - self.v[i]) + L2 * d1 * yy1) * self.bwin(p1, i)\n            return H\n        if m == 6:\n            s, rho, _, _, _, c, _ = self.geom(self.s0)\n            xh1 = self.x0 + math.pi * s * ((c - q1 / LAM) ** 2 - rho ** 2)\n            x2, _ = self.Binv(z2)\n            qw = 1 - sstep((q1 - self.q1_cut) / 3.0)[0]\n            H = 0\n            tw = self.s6_tw\n            for i in TB:\n                W = 1\n                for (a1, a2), cc in self.tri[i]:\n                    W = W * (1 - sstep((a1 * xh1 + a2 * x2 - cc - (1 - tw / 2) * self.g0) / (tw * self.g0))[0])\n                H = H + self.v[i] * q1 * W\n            return H * qw\n        raise ValueError(m)\n\n\n# ---- wc_subset.py ----\n"""Plain toric lattice fallback for any k: the first k slots of the n x n square toric layout (n = ceil sqrt k),\nwritten as axis-legged ToricGeneral pieces (up slots: corner (i,j), signs (+,+); down slots: corner (i+1,j+1),\nsigns (-,-)).  R^2 = n lam - g0, density k / (n lam)^2."""\n\n\ndef square_layout(n):\n    up = [((float(i), float(j)), (1, 1)) for i in range(n) for j in range(n - i)]\n    dn = [((float(i + 1), float(j + 1)), (-1, -1)) for i in range(n - 1) for j in range(n - 1 - i)]\n    slots = up + dn\n    slots.sort(key=lambda c: c[0][0] + c[0][1] + (1 if c[1][0] > 0 else 0))   # inner slots first\n    return slots\n\n\nclass ToricSubset(ToricGeneral):\n    def __init__(self, k, n, **kw):\n        assert k <= n * n\n        super().__init__(k, square_layout(n)[:k], list(range(k)), A=float(n), q1_cut=1e9, **kw)\n\n\n# ---- toric_generic.py ----\n"""Generic toric compiler: any lattice toric layout whose pieces have\nU-frames  P = C + M Delta,  M = [[s1, k], [0, s2]]  (s1, s2 = +-1, k integer; layouts from toric_frames.py).\n\nNine time segments (ToricGeneral numbering in brackets):\n 0 S0  kick p1 += v_i                         [0]\n 1 S1  keyhole stage 1                         [1]\n 2 S2  keyhole stage 2                         [2]\n 3 S3  unwrap of both factors                  [3]\n 4 S4  diagonal part diag(s1, s2) + z2 translation b2         [4]\n 5 W2  global z2 wrap B_s0 -> B_1 (every piece still has y2 in the unit interval: standard branch)\n 6 S5+SH  slide q1 -= X_i + x1 translation d1 [5], CONCURRENT with the shear x1_loc += k x2_src, generator\n       G_sh = k s2 (x2 - b2)(y1_loc - 1/2) in the slide\'s moving strip chart (own flat-top clock).  z2 is already\n       wrapped, so the angle part y2 -= k s2 (y1_loc - 1/2) is a z2 ROTATION by a per-point constant angle\n       (y1_loc static along the flow): single-valued, no branch.  {y1_loc, (x2 - b2)(y1_loc - 1/2)} = 0, so the\n       shear commutes with the d1 translation and with the slide composition rule.  RK4 only damps the rotation,\n       |z2| -> |z2| (1 - Theta^6 / (144 n^5)) for total angle Theta over n flat steps; with Theta <= pi |k| and n ~ 16\n       at N = 100 this is ~6e-6 (a separate 7-step shear segment gave 4e-4 and broke the S6 cell read-out).\n 7 S6  offset removal p1 -= v_i on the final cells (x2 read from the wrapped z2)   [6]\n 8 W1  global z1 wrap (U-frames keep factor 1 diagonal: y1 in the unit interval)   [7, z1 part]\n(A first version sheared in the strip phase and wrapped z2 with a per-band lift; the sheared pieces then have a\ny2 range of length 1 + |k| and the z2 wrap error, which grows like |y - 1/2|^4, was 40x larger: rejected.)\nThe time-1 map sends ball i into the cell lam*C_i + lam*M_i*Delta with lattice gap g0 on all three sides, so\nR^2 <= A lam - g0 as in ToricGeneral.\n"""\nimport math\nimport torch\n\n\ndef _s4(s):\n    a = 2 * math.pi * s\n    S = s - 2 * math.sin(a) / (3 * math.pi) + math.sin(2 * a) / (12 * math.pi)\n    IS = s * s / 2 + (math.cos(a) - 1) / (3 * math.pi ** 2) - (math.cos(2 * a) - 1) / (48 * math.pi ** 2)\n    return S, IS\n\n\ndef sin8_clock(u):\n    u = float(min(max(u, 0.0), 1.0))\n    a = 2 * math.pi * u\n    S = (u - 56 * math.sin(a) / (35 * 2 * math.pi) + 28 * math.sin(2 * a) / (35 * 4 * math.pi)\n         - 8 * math.sin(3 * a) / (35 * 6 * math.pi) + math.sin(4 * a) / (35 * 8 * math.pi))\n    dS = (35 - 56 * math.cos(a) + 28 * math.cos(2 * a) - 8 * math.cos(3 * a) + math.cos(4 * a)) / 35\n    return S, dS\n\n\ndef flat_clock(u, tl, tr):\n    u = float(min(max(u, 0.0), 1.0))\n    A = 1.0 / (1.0 - 0.5 * (tl + tr))\n    if tl > 0 and u < tl:\n        S, IS = _s4(u / tl)\n        return A * tl * IS, A * S\n    if tr > 0 and u > 1 - tr:\n        S, IS = _s4((1 - u) / tr)\n        return 1.0 - A * tr * IS, A * S\n    return A * (0.5 * tl + (u - tl)), A\n\n\nCLK_GEN = (\'sin8\', \'sin4\', \'sin4\', \'sstep\', \'sstep\', \'sstep\', \'sin8\', \'sin8\', \'sstep\')\nSH_CLK = (\'flat\', 0.3, 0.3)\n# segment weights: W2 gets ~21 of 100 steps because S6 reads the cells from the wrapped z2 (needs |dx2| < ~1e-3;\n# measured at k = 30: 14 steps 6.6e-3, 18 steps 1.6e-3, 24 steps 4.8e-4)\nW_GEN = (0.6, 1.3, 0.35, 1.3, 1.15, 2.2, 1.6, 0.7, 1.3)\n\n\nclass ToricGeneric(Toric):\n    def __init__(self, k, pieces, A, g0=3e-3, band=4.4, weights=W_GEN, clock=CLK_GEN, sh_clock=SH_CLK, **kw):\n        """pieces: list of (C, M) in config units, C = (c1, c2), M = ((s1, kk), (0, s2)); ball j -> pieces[j]."""\n        super().__init__(1, g0=g0, band=band, weights=weights, clock=clock, **kw)\n        assert len(pieces) == k and len(self.tb) == 10\n        self.k, self.A = k, A\n        self.sh_clock = sh_clock\n        lam = 1 + 2 * self.d_eff + 3 * g0 - 2 * self.hole\n        self.lam = lam\n        self.R = math.sqrt(A * lam - g0)\n        self.density = k / (A * lam) ** 2\n        self.X = [3.0 * i for i in range(k)]\n        self.v = [band * (i - (k - 1) / 2) for i in range(k)]     # centred kicks (as toric4d)\n        h = g0 - self.hole\n        self.fr, self.pieces, self.tri = [], [], []\n        for (C, M) in pieces:\n            (s1, kk), (z, s2) = M\n            assert z == 0 and abs(s1) == 1 and abs(s2) == 1\n            b = (lam * C[0] + h * (s1 + kk), lam * C[1] + h * s2)\n            self.fr.append((s1, kk, s2))\n            self.pieces.append(((s1, s2), b))\n            # cell lam*C + lam*M*Delta shrunk by g0 (lattice distance); source half-planes n.xi <= c, xi = M^-1 (x - lam C)\n            Mi = ((s1, -kk * s1 * s2), (0, s2))                       # M^-1 for this triangular M\n            cl = (lam * C[0], lam * C[1])\n            rows = []\n            for nvec, cs in (((-1, 0), 0.0), ((0, -1), 0.0), ((1, 1), lam)):\n                a1 = nvec[0] * Mi[0][0] + nvec[1] * Mi[1][0]\n                a2 = nvec[0] * Mi[0][1] + nvec[1] * Mi[1][1]\n                rows.append(((a1, a2), cs + a1 * cl[0] + a2 * cl[1] - g0))\n            self.tri.append(rows)\n\n    # ---------------- clocks\n    def kclk(self, u, kind):\n        if kind == \'sstep\':\n            return pclock(u)\n        if kind == \'sin8\':\n            return sin8_clock(u)\n        if isinstance(kind, (tuple, list)):\n            return flat_clock(u, kind[1], kind[2])\n        return tclock(u, kind)\n\n    def clk(self, u, m):\n        return self.kclk(u, self.clock[m])\n\n    def bwin(self, p1, i):\n        return window(p1 - self.v[i], self.band / 2 - 0.4, 0.2)\n\n    def wrap_K_y(self, w, s, y):\n        s_, rho, rho_p, phi, phi_p, c, c_p = self.geom(s)\n        dq, dp = w[:, 0] - c, w[:, 1]\n        x = self.x0 + math.pi * s_ * (dq ** 2 + dp ** 2 - rho ** 2)\n        Hpol = 2 * math.pi * s_ * rho * rho_p * y - (x - self.x0) * y / s_ - phi_p * (x - self.x0) / (2 * math.pi * s_)\n        return c_p * w[:, 1] + Hpol\n\n    def y1loc(self, q1, p1, i, Su=1.0):\n        return self.Binv(torch.stack([q1 - self.X[i] * (1 - Su), p1 - self.v[i]], 1) / LAM)[1]\n\n    # ---------------- segments\n    def seg_H(self, m, y, u):\n        q1, q2, p1, p2 = y.unbind(1)\n        z2 = torch.stack([q2, p2], 1) / LAM\n        L2 = LAM ** 2\n        rng = range(self.k)\n        if m == 0:\n            H = 0\n            for i in rng:\n                H = H + (-self.v[i]) * (q1 - self.X[i]) * window(q1 - self.X[i], 1.2, 0.5)\n            return H\n        if m in (1, 2):\n            prim = self.kh1 if m == 1 else self.kh2\n            H = L2 * prim(z2)\n            for i in rng:\n                z1 = torch.stack([q1 - self.X[i], p1 - self.v[i]], 1) / LAM\n                H = H + L2 * prim(z1) * self.bwin(p1, i)\n            return H\n        if m == 3:\n            s, dsds = self.sched(float(self.clk(u, m)[0]))\n            H = L2 * self.wrap_K(z2, s)\n            for i in rng:\n                z1 = torch.stack([q1 - self.X[i], p1 - self.v[i]], 1) / LAM\n                H = H + L2 * self.wrap_K(z1, s) * self.bwin(p1, i)\n            return dsds * H\n        if m == 4:\n            x2, yy2 = self.Binv(z2)\n            H = 0\n            for i in rng:\n                sg, b = self.pieces[i]\n                G = 0\n                if sg[0] < 0:\n                    x1, yy1 = self.Binv(torch.stack([q1 - self.X[i], p1 - self.v[i]], 1) / LAM)\n                    G = G + (math.pi / 2) * ((x1 - 0.5) ** 2 + (yy1 - 0.5) ** 2)\n                if sg[1] > 0:\n                    G = G + b[1] * yy2\n                else:\n                    G = G + (math.pi / 2) * ((x2 - b[1] / 2) ** 2 + (yy2 - 0.5) ** 2)\n                H = H + L2 * G * self.bwin(p1, i)\n            return H\n        if m == 5:                                     # z2 wrap (standard branch)\n            S = self.clk(u, m)[0]\n            sig = 1 - float(S)\n            s, dsds = self.sched(sig)\n            return -dsds * L2 * self.wrap_K(z2, s)\n        if m == 6:                                     # slide + x1 translation (clock 6) + shear (clock SH_CLK)\n            Su, dSu = self.clk(u, m)\n            Ssh, dSsh = self.kclk(u, self.sh_clock)\n            H = 0\n            for i in rng:\n                sg, b = self.pieces[i]\n                s1, kk, s2 = self.fr[i]\n                d1 = b[0] if sg[0] > 0 else b[0] - 1.0\n                yl = self.y1loc(q1, p1, i, Su)\n                Hi = dSu * (-self.X[i] * (p1 - self.v[i]) + L2 * d1 * yl)\n                if kk != 0:\n                    x2 = math.pi * z2.square().sum(1)\n                    Hi = Hi + dSsh * L2 * kk * s2 * (x2 - self.pieces[i][1][1]) * (yl - 0.5)\n                H = H + Hi * self.bwin(p1, i)\n            return H\n        if m == 7:                                     # offset removal, x2 from the wrapped z2\n            s_, rho, _, _, _, c, _ = self.geom(self.s0)\n            xh1 = self.x0 + math.pi * s_ * ((c - q1 / LAM) ** 2 - rho ** 2)\n            x2 = math.pi * z2.square().sum(1)\n            H = 0\n            tw = self.s6_tw\n            for i in rng:\n                W = 1\n                for (a1, a2), cc in self.tri[i]:\n                    W = W * (1 - sstep((a1 * xh1 + a2 * x2 - cc - (1 - tw / 2) * self.g0) / (tw * self.g0))[0])\n                H = H + self.v[i] * q1 * W\n            return H\n        if m == 8:                                     # z1 wrap\n            S = self.clk(u, m)[0]\n            sig = 1 - float(S)\n            s, dsds = self.sched(sig)\n            return -dsds * L2 * self.wrap_K(torch.stack([q1, p1], 1) / LAM, s)\n        raise ValueError(m)\n\n    def H(self, Q, P, t):\n        y = torch.cat([Q, P], 1)\n        t = float(t)\n        m = 0\n        while m < 8 and t >= self.tb[m + 1]:\n            m += 1\n        L = self.tb[m + 1] - self.tb[m]\n        u = (t - self.tb[m]) / L\n        if m == 6:                                     # two clocks inside: seg_H returns the full rate\n            return self.seg_H(m, y, u) / L\n        _, dS = self.clk(u, m)\n        return dS / L * self.seg_H(m, y, u)\n\n\n# ---- toric_fast.py ----\n"""Vectorised Hamiltonian for the toric families.\n\nFastToric(T, weights=None, clock=None, sh_clock=None) wraps an instance T of toric4d.Toric (\'square\'),\ntoric_general.ToricGeneral (\'layout\' shear-free, \'subset\') or toric_generic.ToricGeneric (\'layout\' sheared) and\nevaluates the SAME segment Hamiltonians with per-point gathered ball parameters instead of a Python loop over the\nk balls.  Cost per point is independent of k.  Exactness (identical H as a function, not an approximation):\n  * band windows  window(p1 - v_i, band/2 - 0.4, 0.2) vanish exactly for |p1 - v_i| >= band/2 - 0.2 and the v_i\n    are spaced by band, so at most ONE ball (the nearest band) contributes at any point;\n  * kick windows  window(q1 - X_i, 1.2, 0.5) vanish for |q1 - X_i| >= 1.7, X_i = 3 i: at most the two balls\n    floor(q1/3), floor(q1/3) + 1 contribute;\n  * offset-removal cell indicators W_i vanish outside the cell expanded by (1 + tw/2) g0 (lattice distance):\n    a bucket table lists, per bucket of the (x1, x2) moment plane, every cell whose expanded triangle meets it.\nDifferences from the wrapped instance are only in optional knobs: segment weights (time allocation) and clocks.\nRequires every ball to be a toric ball (ToricGeneral parked balls are not supported) and v_i affine in i.\n"""\nimport math\nimport torch\n\n\n\ndef sinp_clock(u, m):\n    """S, S\' with S\' = sin^(2m)(pi u) / mean (closed-form cosine expansion).  Degree-m trigonometric polynomial: RK4\n    (Simpson) integrates it exactly (~1e-16) whenever the segment holds an INTEGER number n > m of steps (any grid\n    offset); for non-integer n the worst-offset error decays like n^-(2m+1) (measured, m = 8: n = 10.3 -> 2.1e-8,\n    n = 12.4 -> 4.1e-10, n = 15.4 -> 5.5e-12; robustness.md section 2.2)."""\n    u = float(min(max(u, 0.0), 1.0))\n    c0 = math.comb(2 * m, m)\n    S, dS = u, 1.0\n    for j in range(1, m + 1):\n        a = 2.0 * (-1) ** j * math.comb(2 * m, m - j) / c0\n        S += a * math.sin(2 * j * math.pi * u) / (2 * j * math.pi)\n        dS += a * math.cos(2 * j * math.pi * u)\n    return S, dS\n\n\ndef clock_eval(u, kind):\n    if kind == \'sstep\':\n        return pclock(u)\n    if kind == \'sin8\':\n        return sin8_clock(u)\n    if isinstance(kind, str) and kind.startswith(\'sin\') and kind not in (\'sin2\', \'sin4\'):\n        return sinp_clock(u, int(kind[3:]) // 2)\n    if isinstance(kind, (tuple, list)):\n        return flat_clock(u, kind[1], kind[2])\n    return tclock(u, kind)\n\n\nclass FastToric:\n    def __init__(self, T, weights=None, clock=None, sh_clock=None, s4split=None, order=\'classic\'):\n        """s4split = (f, rot_clock, trans_clock): split S4 into rotation (u < f) and translation phases.\n        order = \'early\' (8-segment families only): 9-segment early-slide pipeline H_early (weights/clock length 9)."""\n        self.T = T\n        self.s4split = s4split\n        name = type(T).__name__\n        self.generic = hasattr(T, \'fr\')\n        self.order = order\n        assert order == \'classic\' or not self.generic\n        self.nseg = 9 if (self.generic or order == \'early\') else 8\n        k = T.k\n        self.k = k\n        if hasattr(T, \'toric_balls\'):\n            assert list(T.toric_balls) == list(range(k)), \'parked balls not supported\'\n        self.clock = tuple(clock) if clock is not None else tuple(\n            T.clock if not isinstance(T.clock, str) else [T.clock] * self.nseg)\n        assert len(self.clock) == self.nseg\n        self.sh_clock = sh_clock if sh_clock is not None else getattr(T, \'sh_clock\', None)\n        if weights is None:\n            self.tb = list(T.tb)\n        else:\n            assert len(weights) == self.nseg\n            ws = sum(weights); self.tb = [0.0]\n            for w in weights:\n                self.tb.append(self.tb[-1] + w / ws)\n        self.tb[-1] = 1.0\n        X = [3.0 * i for i in range(k)]\n        v = list(T.v)\n        assert all(abs(T.X[i] - X[i]) < 1e-12 for i in range(k))\n        self.band = T.band\n        self.v0 = v[0]\n        assert all(abs(v[i] - (self.v0 + self.band * i)) < 1e-9 for i in range(k)), \'v_i must be affine in i\'\n        # per-ball piece data: sign pair, b, frame shear\n        sg1, sg2, b1, b2, kk, s2f, d1 = [], [], [], [], [], [], []\n        rows = []\n        for i in range(k):\n            if name == \'Toric\' or (not self.generic and not hasattr(T, \'toric_balls\')):\n                kind, b, _ = T.pieces[i]\n                sg = (1, 1) if kind == \'up\' else (-1, -1)\n                tri = T.tri[i]\n            elif self.generic:\n                sg, b = T.pieces[i]\n                tri = T.tri[i]\n            else:\n                sg, b = T.pieces[i]\n                tri = T.tri[i]\n            sg1.append(sg[0]); sg2.append(sg[1]); b1.append(b[0]); b2.append(b[1])\n            d1.append(b[0] if sg[0] > 0 else b[0] - 1.0)\n            if self.generic:\n                s1_, kk_, s2_ = T.fr[i]; kk.append(kk_); s2f.append(s2_)\n            else:\n                kk.append(0); s2f.append(1)\n            rows.append([[a[0], a[1], c] for a, c in tri])\n        t = lambda L: torch.tensor(L, dtype=F64)\n        self.X, self.v = t(X), t(v)\n        self.sg1, self.sg2, self.b1, self.b2, self.d1 = t(sg1), t(sg2), t(b1), t(b2), t(d1)\n        self.kk, self.s2f = t(kk), t(s2f)\n        self.any_shear = any(q != 0 for q in kk)\n        self._build_cells(rows)\n\n    # ---------------- offset-removal bucket table\n    def _build_cells(self, rows):\n        T = self.T\n        g0, tw = T.g0, T.s6_tw\n        off = (1 + tw / 2) * g0 + 1e-9\n        k = self.k\n        boxes = []\n        for r in rows:\n            # expanded triangle: vertices = pairwise intersections of a_r . x = c_r + off\n            P = []\n            for (i, j) in ((0, 1), (1, 2), (0, 2)):\n                a1, a2, c1 = r[i]; e1, e2, c2 = r[j]\n                det = a1 * e2 - a2 * e1\n                assert abs(det) > 1e-12\n                r1, r2 = c1 + off, c2 + off\n                P.append(((r1 * e2 - a2 * r2) / det, (a1 * r2 - r1 * e1) / det))\n            xs = [p[0] for p in P]; ys = [p[1] for p in P]\n            boxes.append((min(xs), max(xs), min(ys), max(ys)))\n        lam = getattr(T, \'lam\', getattr(T, \'cg\', 1.0))\n        hb = 0.5 * lam\n        x_lo = min(b[0] for b in boxes); y_lo = min(b[2] for b in boxes)\n        x_hi = max(b[1] for b in boxes); y_hi = max(b[3] for b in boxes)\n        nx = int(math.floor((x_hi - x_lo) / hb)) + 1; ny = int(math.floor((y_hi - y_lo) / hb)) + 1\n        lists = [[] for _ in range(nx * ny)]\n        for ci, (a, b_, c, d) in enumerate(boxes):\n            for ix in range(max(0, int(math.floor((a - x_lo) / hb))), min(nx - 1, int(math.floor((b_ - x_lo) / hb))) + 1):\n                for iy in range(max(0, int(math.floor((c - y_lo) / hb))), min(ny - 1, int(math.floor((d - y_lo) / hb))) + 1):\n                    lists[ix * ny + iy].append(ci)\n        C = max(1, max(len(l) for l in lists))\n        cand = torch.full((nx * ny + 1, C), k, dtype=torch.long)            # row nx*ny = outside, index k = dummy\n        for bi, l in enumerate(lists):\n            if l:\n                cand[bi, :len(l)] = torch.tensor(l, dtype=torch.long)\n        R = torch.tensor(rows + [[[0.0, 0.0, -1e30]] * 3], dtype=F64)      # (k+1, 3, 3)\n        self.cell_rows = R\n        self.cell_v = torch.cat([self.v, torch.zeros(1, dtype=F64)])\n        self.cand, self.bx = cand, (x_lo, y_lo, hb, nx, ny)\n        self.n_cand = C\n\n    # ---------------- helpers\n    def clk(self, u, m):\n        return clock_eval(u, self.clock[m])\n\n    def band_index(self, p1):\n        i = torch.round((p1.detach() - self.v0) / self.band).long()\n        return i.clamp(0, self.k - 1)\n\n    def bwin(self, p1, vi):\n        return window(p1 - vi, self.band / 2 - 0.4, 0.2)\n\n    def z1loc(self, q1, p1, Xi, vi):\n        return torch.stack([q1 - Xi, p1 - vi], 1) / LAM\n\n    def kick(self, q1):\n        j0 = torch.floor(q1.detach() / 3.0).long()\n        H = 0\n        for j in (j0, j0 + 1):\n            ok = ((j >= 0) & (j < self.k)).to(F64)\n            jc = j.clamp(0, self.k - 1)\n            Xj, vj = self.X[jc], self.v[jc]\n            H = H + ok * (-vj) * (q1 - Xj) * window(q1 - Xj, 1.2, 0.5)\n        return H\n\n    def offset(self, q1, xh1, x2):\n        x_lo, y_lo, hb, nx, ny = self.bx\n        ix = torch.floor((xh1.detach() - x_lo) / hb).long(); iy = torch.floor((x2.detach() - y_lo) / hb).long()\n        inside = (ix >= 0) & (ix < nx) & (iy >= 0) & (iy < ny)\n        bid = torch.where(inside, ix.clamp(0, nx - 1) * ny + iy.clamp(0, ny - 1), torch.full_like(ix, nx * ny))\n        cidx = self.cand[bid]                                               # (n, C)\n        R = self.cell_rows[cidx]                                            # (n, C, 3, 3)\n        g0, tw = self.T.g0, self.T.s6_tw\n        arg = (R[..., 0] * xh1[:, None, None] + R[..., 1] * x2[:, None, None] - R[..., 2]\n               - (1 - tw / 2) * g0) / (tw * g0)\n        W = (1 - sstep(arg)[0]).prod(-1)                                    # (n, C)\n        return q1 * (self.cell_v[cidx] * W).sum(1)\n\n    # ---------------- early-slide order (8-segment families only; order=\'early\')\n    def H_early(self, Q, P, t):\n        """Segments: 0 kick p1 += v_i | 1 slide q1 -= X_i (pure translation of the round ball) | 2 kh1 | 3 kh2 |\n        4 unwrap | 5 S4 rotations by pi about the local centres (pure) | 6 strip translations d1 (z1) and c2 (z2), static\n        charts, commuting, linear | 7 offset removal | 8 joint wrap.  All z1-local stages of the classic order are\n        conjugated by the q1 translation, so the time-1 map is the same; no stage has a moving chart."""\n        T = self.T\n        q1, q2, p1, p2 = torch.cat([Q, P], 1).unbind(1)\n        t = float(t)\n        m = 0\n        while m < 8 and t >= self.tb[m + 1]:\n            m += 1\n        L = self.tb[m + 1] - self.tb[m]\n        u = (t - self.tb[m]) / L\n        S, dS = self.clk(u, m)\n        r = dS / L\n        z2 = torch.stack([q2, p2], 1) / LAM\n        L2 = LAM ** 2\n        if m == 0:\n            return r * self.kick(q1)\n        i = self.band_index(p1); vi = self.v[i]\n        bw = self.bwin(p1, vi)\n        z1 = torch.stack([q1, p1 - vi], 1) / LAM\n        if m == 1:\n            return r * (-self.X[i] * (p1 - vi)) * bw\n        if m in (2, 3):\n            prim = T.kh1 if m == 2 else T.kh2\n            return r * L2 * (prim(z2) + prim(z1) * bw)\n        if m == 4:\n            s, dsds = T.sched(float(S))\n            return r * dsds * L2 * (T.wrap_K(z2, s) + T.wrap_K(z1, s) * bw)\n        if m in (5, 6):\n            x2, yy2 = T.Binv(z2); x1, yy1 = T.Binv(z1)\n            sg1, sg2, b2 = self.sg1[i], self.sg2[i], self.b2[i]\n            if m == 5:\n                G = (math.pi / 2) * ((sg1 < 0).to(F64) * ((x1 - 0.5) ** 2 + (yy1 - 0.5) ** 2)\n                                     + (sg2 < 0).to(F64) * ((x2 - 0.5) ** 2 + (yy2 - 0.5) ** 2))\n            else:\n                G = self.d1[i] * yy1 + torch.where(sg2 > 0, b2, b2 - 1.0) * yy2\n            return r * L2 * G * bw\n        if m == 7:\n            s_, rho, _, _, _, c, _ = T.geom(T.s0)\n            xh1 = T.x0 + math.pi * s_ * ((c - q1 / LAM) ** 2 - rho ** 2)\n            return r * self.offset(q1, xh1, T.Binv(z2)[0])\n        s, dsds = T.sched(1 - float(S))\n        return r * (-dsds) * L2 * (T.wrap_K(z2, s) + T.wrap_K(torch.stack([q1, p1], 1) / LAM, s))\n\n    # ---------------- Hamiltonian\n    def H(self, Q, P, t):\n        if self.order == \'early\':\n            return self.H_early(Q, P, t)\n        T = self.T\n        q1, q2, p1, p2 = torch.cat([Q, P], 1).unbind(1)     # cat: every input is in the autograd graph\n        t = float(t)\n        m = 0\n        while m < self.nseg - 1 and t >= self.tb[m + 1]:\n            m += 1\n        L = self.tb[m + 1] - self.tb[m]\n        u = (t - self.tb[m]) / L\n        z2 = torch.stack([q2, p2], 1) / LAM\n        L2 = LAM ** 2\n        g = self.generic\n        if m == 0:\n            S, dS = self.clk(u, m)\n            return dS / L * self.kick(q1)\n        if m in (1, 2):\n            S, dS = self.clk(u, m)\n            prim = T.kh1 if m == 1 else T.kh2\n            i = self.band_index(p1); Xi, vi = self.X[i], self.v[i]\n            return dS / L * L2 * (prim(z2) + prim(self.z1loc(q1, p1, Xi, vi)) * self.bwin(p1, vi))\n        if m == 3:\n            S, dS = self.clk(u, m)\n            s, dsds = T.sched(float(S))\n            i = self.band_index(p1); Xi, vi = self.X[i], self.v[i]\n            Hs = T.wrap_K(z2, s) + T.wrap_K(self.z1loc(q1, p1, Xi, vi), s) * self.bwin(p1, vi)\n            return dS / L * dsds * L2 * Hs\n        if m == 4 and self.s4split is not None:\n            # split S4: phase A (u < f) rotations by pi about the LOCAL centre (1/2, 1/2) of each flipped factor\n            # (radius <= 0.71 instead of b2/2); phase B (u >= f) strip translation of x2 by b2 (up) or b2 - 1\n            # (flipped), linear in the strip chart, with a high-order clock (quadrature-exact to ~1e-7).\n            # Endpoint map identical to the joint rotation about (b2/2, 1/2): x2 -> b2 - x2, y2 -> 1 - y2.\n            f, ck_r, ck_t = self.s4split\n            i = self.band_index(p1); Xi, vi = self.X[i], self.v[i]\n            x2, yy2 = T.Binv(z2)\n            sg1, sg2, b2 = self.sg1[i], self.sg2[i], self.b2[i]\n            if f in (\'conc\', \'conc_d1\'):\n                # concurrent: x2 translation a(u) = c2 S_t(u) (c2 = b2 or b2 - 1) and rotation by pi about the MOVING\n                # local centre (1/2 + a(u), 1/2); generator of T_a(u) o R(theta(u)) = a\' y2 + theta\'/2 |x - a - c|^2.\n                # \'conc_d1\' (8-segment families only): the z1 strip translation d1 of the slide stage is done here too,\n                # in the LOCAL z1 chart (same chart as the global one after the q1 slide), so the slide becomes the pure\n                # translation q1 -= X_i (no moving chart: robust for large X_i).\n                Sr, dSr = clock_eval(u, ck_r); St, dSt = clock_eval(u, ck_t)\n                c2 = torch.where(sg2 > 0, b2, b2 - 1.0)\n                x1, yy1 = T.Binv(self.z1loc(q1, p1, Xi, vi))\n                c1 = self.d1[i] if f == \'conc_d1\' else torch.zeros_like(c2)\n                G = dSt * (c2 * yy2 + c1 * yy1) + dSr * (math.pi / 2) * (\n                    (sg1 < 0).to(F64) * ((x1 - 0.5 - c1 * St) ** 2 + (yy1 - 0.5) ** 2)\n                    + (sg2 < 0).to(F64) * ((x2 - 0.5 - c2 * St) ** 2 + (yy2 - 0.5) ** 2))\n                return G * L2 * self.bwin(p1, vi) / L\n            if u < f:\n                _, dS = clock_eval(u / f, ck_r)\n                x1, yy1 = T.Binv(self.z1loc(q1, p1, Xi, vi))\n                G = ((sg1 < 0).to(F64) * ((x1 - 0.5) ** 2 + (yy1 - 0.5) ** 2)\n                     + (sg2 < 0).to(F64) * ((x2 - 0.5) ** 2 + (yy2 - 0.5) ** 2)) * (math.pi / 2)\n                return dS / (f * L) * L2 * G * self.bwin(p1, vi)\n            _, dS = clock_eval((u - f) / (1 - f), ck_t)\n            G = torch.where(sg2 > 0, b2, b2 - 1.0) * yy2\n            return dS / ((1 - f) * L) * L2 * G * self.bwin(p1, vi)\n        if m == 4:\n            S, dS = self.clk(u, m)\n            i = self.band_index(p1); Xi, vi = self.X[i], self.v[i]\n            x2, yy2 = T.Binv(z2)\n            x1, yy1 = T.Binv(self.z1loc(q1, p1, Xi, vi))\n            sg1, sg2, b2 = self.sg1[i], self.sg2[i], self.b2[i]\n            G = ((sg1 < 0).to(F64) * (math.pi / 2) * ((x1 - 0.5) ** 2 + (yy1 - 0.5) ** 2)\n                 + (sg2 > 0).to(F64) * b2 * yy2\n                 + (sg2 < 0).to(F64) * (math.pi / 2) * ((x2 - b2 / 2) ** 2 + (yy2 - 0.5) ** 2))\n            return dS / L * L2 * G * self.bwin(p1, vi)\n        if g and m in (5, 8):                       # generic: z2 wrap (5), z1 wrap (8)\n            S, dS = self.clk(u, m)\n            s, dsds = T.sched(1 - float(S))\n            w = z2 if m == 5 else torch.stack([q1, p1], 1) / LAM\n            return dS / L * (-dsds) * L2 * T.wrap_K(w, s)\n        if (not g and m == 5) or (g and m == 6):    # slide (+ concurrent shear for generic)\n            Su, dSu = self.clk(u, m)\n            i = self.band_index(p1); Xi, vi = self.X[i], self.v[i]\n            if not g and self.s4split is not None and self.s4split[0] == \'conc_d1\':\n                return dSu * (-Xi * (p1 - vi)) * self.bwin(p1, vi) / L        # pure q1 translation (d1 done in S4)\n            yl = T.Binv(torch.stack([q1 - Xi * (1 - Su), p1 - vi], 1) / LAM)[1]\n            Hi = dSu * (-Xi * (p1 - vi) + L2 * self.d1[i] * yl)\n            if g and self.any_shear:\n                Ssh, dSsh = clock_eval(u, self.sh_clock)\n                x2 = math.pi * z2.square().sum(1)\n                Hi = Hi + dSsh * L2 * self.kk[i] * self.s2f[i] * (x2 - self.b2[i]) * (yl - 0.5)\n            return Hi * self.bwin(p1, vi) / L\n        if (not g and m == 6) or (g and m == 7):    # offset removal\n            S, dS = self.clk(u, m)\n            s_, rho, _, _, _, c, _ = T.geom(T.s0)\n            xh1 = T.x0 + math.pi * s_ * ((c - q1 / LAM) ** 2 - rho ** 2)\n            x2 = math.pi * z2.square().sum(1) if g else T.Binv(z2)[0]\n            return dS / L * self.offset(q1, xh1, x2)\n        if not g and m == 7:                        # joint wrap\n            S, dS = self.clk(u, m)\n            s, dsds = T.sched(1 - float(S))\n            return dS / L * (-dsds) * L2 * (T.wrap_K(z2, s) + T.wrap_K(torch.stack([q1, p1], 1) / LAM, s))\n        raise ValueError(m)\n'
PLAN_SRC = '"""Planner: chooses the layout and the small parameters as functions of (k, epsilon) (generated source)."""\nimport math\n\nREG_L = (0.012, dict(kh=(0.015, 9.0, 3e-3, 0.1, 1e-2), kh_out=(0.0150, 9.3e-7)))\nREG_S = (0.003, dict(kh=(0.004, 9.0, 1e-4, 0.05, 3e-3), kh_out=(0.004, 0.0)))\nSLACK = 0.996            # further regimes: target R^2 = 0.996 sqrt(k / (1 - eps))\nG0_MAX = 0.05\nSIGMA = 0.15             # regime E: fraction of the budget beta kept as R^2 margin\nU_MIN = 5e-5             # regime E: smallest scale (d = 2e-4, g0 = 1.5e-4); overhead in eps ~ 0.002 above the static deficit\nD_REF, CIN_REF = 0.004, 9.0\nK_MAX = 100000           # largest k (RK4 evidence on sampled balls up to k = 99856;\nA_SH_MAX = 10.0          # sheared (ToricGeneric) layouts only for A <= A_SH_MAX (library has none above)\n\n\ndef kh_params(d):\n    """eps-scaled keyhole, the self-similar continuation of REG_S: (drel, c_in, xc, CT, XG)."""\n    return (0.97 * math.log1p(d), CIN_REF + math.log(D_REF / d), 0.025 * d, 0.05 * math.sqrt(d / D_REF), 0.75 * d)\n\n\ndef kh_margin(kh):\n    """Closed-form validity margin of a keyhole: the image of the closed unit disc misses the cut\n    ray {p = 0, q >= 0} iff the returned number (e-folds of x on the invariant ray phi = 0) is positive."""\n    drel, cin, xc, CT, XG = kh\n\n    def I(q, n=400):\n        h = q / n\n        s = 0.0\n        for j in range(n + 1):\n            s += (1 if j in (0, n) else (4 if j % 2 else 2)) * math.exp(math.pi * (j * h) ** 2 / XG)\n        return s * h / 3\n    lo, hi = 0.0, 5 * math.sqrt(XG / math.pi)\n    for _ in range(60):\n        mid = 0.5 * (lo + hi)\n        lo, hi = (mid, hi) if I(mid) < CT else (lo, mid)\n    x_c = math.pi * (0.5 * (lo + hi)) ** 2\n    G = lambda x: math.log(x) - xc ** 3 / (3 * x ** 3)\n    return G(x_c) + (cin - drel) - G(1.0)\n\n\ndef ray_dist(d):\n    """measured distance of the keyholed disc to the cut ray (empirical fit)."""\n    return 6.2e-5 * (d / D_REF) ** 1.5\n\n\ndef regime(dens, eps, A):\n    """small parameters for a layout of static density dens at strip length A, or None (eps too small)."""\n    lam_t = math.sqrt(dens / (1 - eps))\n    s0_cap = 1 / (16 * math.pi * A)\n    for name, (gmin, kw) in ((\'L\', REG_L), (\'S\', REG_S)):\n        d_eff, hole = kw[\'kh_out\']\n        g0 = (lam_t * SLACK - 1 - 2 * d_eff + 2 * hole) / 3\n        if g0 >= gmin:\n            g0 = min(g0, G0_MAX)\n            return dict(regime=name, g0=g0, kh=kw[\'kh\'], kh_out=kw[\'kh_out\'], s0=min(0.001, s0_cap), x0=4e-7,\n                        lam=1 + 2 * d_eff + 3 * g0 - 2 * hole, u=g0 / 3)\n    u = (1 - SIGMA) * (lam_t - 1) / 17\n    if u < U_MIN:\n        return None\n    d, g0 = 4 * u, 3 * u\n    kh = kh_params(d)\n    return dict(regime=\'E\', g0=g0, kh=kh, kh_out=(d, 0.0), s0=min(g0 / 3, s0_cap),\n                x0=min(4e-7, 0.25 * ray_dist(d)), lam=1 + 2 * d + 3 * g0, u=u)\n\n\ndef eps_floor(dens):\n    """infimum of the eps reachable by regime(): u = U_MIN."""\n    return 1 - dens / (1 + 17 * U_MIN / (1 - SIGMA)) ** 2\n\n\ndef steps_for(A, u, sheared):\n    """recommended RK4 step count N = 2 x (smallest passing step count of the scan in, taken at the\n    next larger tested strip length A in {4, 30, 100, 316} and the next smaller tested scale u in {1e-3, 2.5e-4,\n    5e-5}); a multiple of 100, so every segment of FAST8 / FAST9 holds an integer number of steps."""\n    if A <= 4:\n        Np = 200\n    elif A <= 30:\n        Np = 200 if u >= 1e-3 else 400\n    elif A <= 100:\n        Np = 400 if u >= 1e-3 else 800\n    else:\n        Np = 800 if u >= 2.5e-4 else 1600\n    if sheared:                              # ToricGeneric / FAST9 (tested up to A = 28/3)\n        Np = max(Np, 400 if A <= 7.5 else 800)\n    return 2 * Np\n\n\ndef options(k, LIB, MAXHEAD):\n    """all lattice options for k: (kind, n, m, n_sheared, payload)."""\n    out = []\n    n = int(round(math.sqrt(k)))\n    if n * n == k:\n        out.append((\'square\', n, 1, 0, None))\n    for (nn, mm, nsh, pcs) in LIB.get(k, []):\n        if nsh == 0 or nn / mm <= A_SH_MAX:\n            out.append((\'layout\', nn, mm, nsh, pcs))\n    ns = math.ceil(math.sqrt(k) - 1e-12)\n    for idx, (nn, mm, cnt) in enumerate(MAXHEAD):\n        if cnt >= k and nn < ns * mm:\n            out.append((\'sublayout\', nn, mm, 0, idx))\n    if ns * ns != k:\n        out.append((\'subset\', ns, 1, 0, None))\n    return out\n\n\nRANK = {\'square\': 0, \'layout\': 1, \'sublayout\': 2, \'subset\': 3}\n\n\ndef reach(k, LIB, MAXHEAD):\n    """{label: eps floor} for every option of k."""\n    out = {}\n    for kind, nn, mm, nsh, _ in options(k, LIB, MAXHEAD):\n        lab = kind + (\' A=%d/%d\' % (nn, mm) if mm > 1 else \' A=%d\' % nn) + (\' sheared=%d\' % nsh if nsh else \'\')\n        out[lab] = eps_floor(k * mm * mm / (nn * nn))\n    return out\n\n\ndef plan(k, eps, LIB, MAXHEAD):\n    """(family kind, parameters, density bound, recommended steps); NotImplementedError when eps is out of reach.\n    Preference: shear-free options first (largest static density, i.e. largest parameter scale), then sheared."""\n    if isinstance(k, bool) or int(k) != k or k < 10 or not (0 < float(eps) < 1):\n        raise ValueError(\'require integer k >= 10 and 0 < epsilon < 1\')\n    k, eps = int(k), float(eps)\n    if k > K_MAX:\n        raise NotImplementedError(f\'(k={k}, eps={eps}) not covered: k > {K_MAX} is outside the RK4-tested range of the \'\n                                  \'lattice-toric families (the exact flow still packs)\')\n    best = None\n    for kind, nn, mm, nsh, payload in options(k, LIB, MAXHEAD):\n        dens = k * mm * mm / (nn * nn)\n        reg = regime(dens, eps, nn / mm)\n        if reg is None:\n            continue\n        key = (nsh > 0, -dens, RANK[kind])\n        if best is None or key < best[0]:\n            best = (key, kind, nn, mm, nsh, payload, reg, dens)\n    if best is None:\n        r = reach(k, LIB, MAXHEAD)\n        raise NotImplementedError(f\'(k={k}, eps={eps}) not covered by the lattice-toric families; reach: eps > \'\n                                  f\'{min(r.values()):.4f} (\' + \', \'.join(f\'{f}: {v:.4f}\' for f, v in r.items()) + \')\')\n    _, kind, nn, mm, nsh, payload, reg, dens = best\n    assert kh_margin(reg[\'kh\']) > 1.0          # closed-form keyhole validity\n    par = dict(n=nn, m=mm, sheared=nsh, payload=payload, **reg)\n    Rb2 = nn / mm * reg[\'lam\'] - (reg[\'g0\'] if kind != \'square\' else 0.0)\n    return kind, par, k / Rb2 ** 2, steps_for(nn / mm, reg[\'u\'], nsh > 0)\n'
