EXT_SRC = {'k10_sw2': '"""Building block: k = 10 sheared-window packing at A = 19/6 L (generated source)."""\nSRC = \'"""Lattice-toric packing for k = n^2, built from segments that RK4 integrates accurately.\\n\\nCoordinates y = (q1, q2, p1, p2), z1 = (q1, p1), z2 = (q2, p2), omega = dq^dp, X_H = (H_p, -H_q).\\nInitial ball i (i = 0..k-1) has centre (3i, 0, 0, 0) and radius 1; each factor disc has area pi.\\nPlanar primitives are designed for unit area and rescaled by H_lam(w) = lam^2 H(w/lam) (lam = sqrt(pi)).\\n\\nTime segments (1/8 each):\\n S0 vertical kick: p1 += v_i (shear depending on q1 only)\\n S1 keyhole, phase 1 (z1 local about each ball centre; z2 global)\\n S2 keyhole, phase 2 (local translation)\\n S3 both factors wrapped backwards B_1 -> B_s0 (z1 about each ball centre, z2 about 0)\\n S4 linear transport of each piece in strip coordinates (upper triangle: translate by b; lower: turn by pi about (b\\\'/2, 1/2))\\n S5 horizontal translation q1 -= X_i (shear depending on p1 only)\\n S6 remove the vertical offset p1 -= v_i (shear depending on (q1, z2), with constant gradient on each triangle)\\n S7 both factors wrapped globally B_s0 -> B_1\\n"""\\nimport math\\nimport torch\\n\\nF64 = torch.float64\\nLAM = math.sqrt(math.pi)\\n\\n\\ndef sstep(u):\\n    """Flat smooth step (scalar or tensor) and its derivative."""\\n    u = torch.as_tensor(u, dtype=F64).clamp(0, 1)\\n    e1 = torch.where(u > 0, torch.exp(-1 / u.clamp_min(1e-300)), torch.zeros_like(u))\\n    e2 = torch.where(u < 1, torch.exp(-1 / (1 - u).clamp_min(1e-300)), torch.zeros_like(u))\\n    d1 = torch.where(u > 0, e1 / u.clamp_min(1e-300) ** 2, torch.zeros_like(u))\\n    d2 = torch.where(u < 1, -e2 / (1 - u).clamp_min(1e-300) ** 2, torch.zeros_like(u))\\n    return e1 / (e1 + e2), (d1 * e2 - e1 * d2) / (e1 + e2) ** 2\\n\\n\\ndef tclock(u, kind):\\n    """Trigonometric-polynomial clocks: \\\'sin2\\\' S\\\' = 1 - cos 2 pi u (vanishing to order 2 at the ends); \\\'sin4\\\' S\\\' = (8/3) sin^4 pi u (order 4).\\n    All derivatives are moderate, unlike sstep, whose exp(-1/u) transition has very large higher derivatives."""\\n    u = float(min(max(u, 0.0), 1.0))\\n    a = 2 * math.pi * u\\n    if kind == \\\'sin2\\\':\\n        return u - math.sin(a) / (2 * math.pi), 1 - math.cos(a)\\n    if kind == \\\'sin4\\\':\\n        return (u - 2 * math.sin(a) / (3 * math.pi) + math.sin(2 * a) / (12 * math.pi),\\n                1 - 4 * math.cos(a) / 3 + math.cos(2 * a) / 3)\\n    raise ValueError(kind)\\n\\n\\n_GL_X, _GL_W = None, None\\n\\n\\ndef pclock(u, tau=None, nodes=64):\\n    """Clock S(u), S\\\'(u). tau=None: flat step (default). Given tau: plateau clock S\\\' proportional to sstep(u/tau) sstep((1-u)/tau).\\n    With tau=0.15 the transitions are so steep that the Simpson quadrature error grows about 100-fold, so this is not the default."""\\n    if tau is None:\\n        S, dS = sstep(torch.tensor(float(min(max(u, 0.0), 1.0)), dtype=F64))\\n        return float(S), float(dS)\\n    global _GL_X, _GL_W\\n    if _GL_X is None:\\n        import numpy as _np\\n        xg, wg = _np.polynomial.legendre.leggauss(nodes)\\n        _GL_X, _GL_W = torch.tensor(xg, dtype=F64), torch.tensor(wg, dtype=F64)\\n\\n    def b(v):\\n        return sstep(v / tau)[0] * sstep((1 - v) / tau)[0]\\n\\n    def integ(a, c):\\n        tot = 0.0\\n        for j in range(4):\\n            a0, a1 = a + (c - a) * j / 4, a + (c - a) * (j + 1) / 4\\n            tot = tot + 0.5 * (a1 - a0) * (_GL_W * b(a0 + 0.5 * (a1 - a0) * (_GL_X + 1))).sum()\\n        return tot\\n    u = float(min(max(u, 0.0), 1.0))\\n    Z = integ(0.0, 1.0)\\n    return float(integ(0.0, u) / Z), float(b(torch.tensor(u, dtype=F64)) / Z)\\n\\n\\ndef window(z, half, trans):\\n    """Smooth window: 1 for |z| <= half, 0 for |z| >= half + trans."""\\n    return 1 - sstep((z.abs() - half) / trans)[0]\\n\\n\\nclass Toric:\\n    def __init__(self, n, g0=0.02, kh=(0.015, 9.0, 3e-3, 0.1, 1e-2), kh_out=(0.0150, 9.3e-7),\\n                 x0=4e-7, kappa=1 / (2 * math.pi), s0=0.005, band=4.4,\\n                 weights=(1.1, 1.1, 0.35, 1.3, 1.0, 1.35, 1.15, 1.65), Lam_s=7.0,\\n                 schedule=\\\'lin\\\', logit_d=2e-3, clock=\\\'sstep\\\', s6_tw=0.6):\\n        self.n, self.k = n, n * n\\n        self.clock = clock\\n        self.s6_tw = s6_tw\\n        # scale-invariant keyhole: (delta_rel, c_in, xc, CT, XG)\\n        self.drel, self.cin, self.xc, self.CT, self.XG = kh\\n        self.w_kh = self.drel / self.cin\\n        # measured keyhole data (units a = 1): effective delta and hole\\n        self.d_eff, self.hole = kh_out\\n        wsum = sum(weights)\\n        self.tb = [0.0]\\n        for wgt in weights:\\n            self.tb.append(self.tb[-1] + wgt / wsum)\\n        self.x0, self.kappa, self.s0 = x0, kappa, s0\\n        self.Lam_s = Lam_s\\n        self.schedule, self.logit_d = schedule, logit_d\\n        self.rho1 = math.sqrt(x0 / math.pi)\\n        self.g0 = g0\\n        self.cg = 1 + 2 * self.d_eff + 3 * g0 - 2 * self.hole\\n        self.R = math.sqrt(n * self.cg)\\n        self.density = 1 / self.cg ** 2\\n        k = self.k\\n        self.X = [3.0 * i for i in range(k)]\\n        self.v = [band * (i - (k - 1) / 2) for i in range(k)]\\n        self.band = band\\n        # triangles and placement: upper triangles (i,j), i+j<=n-1; lower triangles (i,j), i+j<=n-2\\n        pieces = []\\n        for i in range(n):\\n            for j in range(n - i):\\n                b = (i * self.cg + g0 - self.hole, j * self.cg + g0 - self.hole)\\n                pieces.append((\\\'up\\\', b, ((i * self.cg, j * self.cg), \\\'up\\\')))\\n        for i in range(n - 1):\\n            for j in range(n - 1 - i):\\n                bp = ((i + 1) * self.cg - g0 + self.hole, (j + 1) * self.cg - g0 + self.hole)\\n                pieces.append((\\\'down\\\', bp, (((i + 1) * self.cg, (j + 1) * self.cg), \\\'down\\\')))\\n        assert len(pieces) == k\\n        self.pieces = pieces\\n        # the three half-planes (a.x <= c) of each target triangle, for the smooth indicator of S6\\n        self.tri = []\\n        for kind, _, (corner, _) in pieces:\\n            cx, cy = corner\\n            if kind == \\\'up\\\':\\n                self.tri.append([((-1, 0), -(cx + g0)), ((0, -1), -(cy + g0)), ((1, 1), cx + cy + self.cg - g0)])\\n            else:\\n                self.tri.append([((1, 0), cx - g0), ((0, 1), cy - g0), ((-1, -1), -(cx + cy - self.cg + g0))])\\n\\n    def clk(self, u, m):\\n        kind = self.clock if isinstance(self.clock, str) else self.clock[m]\\n        return pclock(u) if kind == \\\'sstep\\\' else tclock(u, kind)\\n\\n    def sched(self, sig):\\n        """Wrapping parameter s(sigma), sigma in [0,1], s(0)=1, s(1)=s0; returns (s, ds/dsigma)."""\\n        s0 = self.s0\\n        if self.schedule == \\\'lin\\\':\\n            return 1 - (1 - s0) * sig, -(1 - s0)\\n        if self.schedule == \\\'exp\\\':\\n            Lm = self.Lam_s; e = math.exp(Lm * sig); D = math.exp(Lm) - 1\\n            return 1 - (1 - s0) * (e - 1) / D, -(1 - s0) * Lm * e / D\\n        # logit: l = log(s / (1 - s + d1)) is linear in sigma, from l(1) to l(s0)\\n        d1 = self.logit_d\\n        l0, l1 = math.log(1 / d1), math.log(s0 / (1 - s0 + d1))\\n        l = l0 + (l1 - l0) * sig\\n        E = math.exp(l)                       # s = E (1 - s + d1)  =>  s = E (1 + d1) / (1 + E)\\n        s = E * (1 + d1) / (1 + E)\\n        dsdl = (1 + d1) * E / (1 + E) ** 2\\n        return s, dsdl * (l1 - l0)\\n\\n    # ---------- planar primitives (unit-area coordinate w, shape (N,2)) ----------\\n    def kh1(self, w):\\n        x = math.pi * w.square().sum(1)\\n        phi = torch.atan2(w[:, 1], w[:, 0]) / (2 * math.pi)\\n        F = x ** 3 / (x ** 3 + self.xc ** 3)\\n        S = self.drel * (sstep((phi / self.w_kh + 1) / 2)[0] - 0.5 - phi)\\n        cut = 1 - sstep((x - 1.3) / 0.5)[0]\\n        return -x * F * S * cut\\n\\n    def kh2(self, w):\\n        x = math.pi * w.square().sum(1)\\n        return -self.CT * torch.exp(-x / self.XG) * w[:, 1]\\n\\n    def geom(self, s):\\n        s = torch.as_tensor(s, dtype=F64)\\n        rho2 = self.x0 / math.pi + self.kappa ** 2 * (1 / s - 1) ** 2\\n        rho = rho2.sqrt(); rho_p = -self.kappa ** 2 * (1 / s - 1) / s ** 2 / rho\\n        phi = math.pi - math.pi * s\\n        return s, rho, rho_p, phi, -math.pi, rho - self.rho1, rho_p\\n\\n    def wrap_K(self, w, s):\\n        """Generator K_s of d/ds (unit-area coordinates)."""\\n        s, rho, rho_p, phi, phi_p, c, c_p = self.geom(s)\\n        dq, dp = w[:, 0] - c, w[:, 1]\\n        x = self.x0 + math.pi * s * (dq ** 2 + dp ** 2 - rho ** 2)\\n        base = phi - math.pi * (1 - s)\\n        ang = torch.remainder(torch.atan2(dp, dq) - base, 2 * math.pi) + base\\n        y = (ang - phi) / (2 * math.pi * s)\\n        Hpol = 2 * math.pi * s * rho * rho_p * y - (x - self.x0) * y / s - phi_p * (x - self.x0) / (2 * math.pi * s)\\n        return c_p * w[:, 1] + Hpol\\n\\n    def Binv(self, w, s=None):\\n        """Inverse of B_s (unit-area coordinates -> (x, y)), default s = s0; the branch cut is opposite the sector."""\\n        s, rho, _, phi, _, c, _ = self.geom(self.s0 if s is None else s)\\n        dq, dp = w[:, 0] - c, w[:, 1]\\n        x = self.x0 + math.pi * s * (dq ** 2 + dp ** 2 - rho ** 2)\\n        base = phi - math.pi * (1 - s)\\n        ang = torch.remainder(torch.atan2(dp, dq) - base, 2 * math.pi) + base\\n        return x, (ang - phi) / (2 * math.pi * s)\\n\\n    def B(self, x, y, s=None):\\n        s, rho, _, phi, _, c, _ = self.geom(self.s0 if s is None else s)\\n        r = (rho ** 2 + (x - self.x0) / (math.pi * s)).sqrt(); th = 2 * math.pi * s * y + phi\\n        return torch.stack([c + r * th.cos(), r * th.sin()], -1)\\n\\n    # ---------- Hamiltonian of each time segment (real coordinates y (N,4); returns (N,)) ----------\\n    def seg_H(self, m, y, u):\\n        q1, q2, p1, p2 = y.unbind(1)\\n        z2 = torch.stack([q2, p2], 1) / LAM\\n        k = self.k\\n        S, dS = self.clk(u, m)\\n        L2 = LAM ** 2\\n        if m == 0:      # vertical kick\\n            H = 0\\n            for i in range(k):\\n                H = H + (-self.v[i]) * (q1 - self.X[i]) * window(q1 - self.X[i], 1.2, 0.5)\\n            return H\\n        if m in (1, 2):  # keyhole\\n            prim = self.kh1 if m == 1 else self.kh2\\n            H = L2 * prim(z2)\\n            for i in range(k):\\n                z1 = torch.stack([q1 - self.X[i], p1 - self.v[i]], 1) / LAM\\n                H = H + L2 * prim(z1) * window(p1 - self.v[i], self.band / 2 - 0.4, 0.2)\\n            return H\\n        if m in (3, 7):  # wrapping: S3 backwards (s: 1 -> s0), S7 forwards (s0 -> 1)\\n            # 1-s grows exponentially in sigma: near s = 1 the relative growth rate of the inner radius is at most Lam_s\\n            sig = float(S) if m == 3 else 1 - float(S)      # sigma: 0 means s=1, 1 means s=s0\\n            s, dsds = self.sched(sig)\\n            sdot = dsds if m == 3 else -dsds\\n            H = L2 * self.wrap_K(z2, s)\\n            if m == 3:\\n                for i in range(k):\\n                    z1 = torch.stack([q1 - self.X[i], p1 - self.v[i]], 1) / LAM\\n                    H = H + L2 * self.wrap_K(z1, s) * window(p1 - self.v[i], self.band / 2 - 0.4, 0.2)\\n            else:\\n                H = H + L2 * self.wrap_K(torch.stack([q1, p1], 1) / LAM, s)\\n            return sdot * H\\n        if m == 4:      # z1: lower triangles turn by pi about their centre; z2: full linear transport (upper: translate by b2; lower: turn by pi about (b2\\\'/2,1/2))\\n            x2, yy2 = self.Binv(z2)\\n            H = 0\\n            for i in range(k):\\n                kind, b, _ = self.pieces[i]\\n                if kind == \\\'up\\\':\\n                    G = b[1] * yy2\\n                else:\\n                    x1, yy1 = self.Binv(torch.stack([q1 - self.X[i], p1 - self.v[i]], 1) / LAM)\\n                    G = (math.pi / 2) * ((x1 - 0.5) ** 2 + (yy1 - 0.5) ** 2 + (x2 - b[1] / 2) ** 2 + (yy2 - 0.5) ** 2)\\n                H = H + L2 * G * window(p1 - self.v[i], self.band / 2 - 0.4, 0.2)\\n            return H\\n        if m == 5:      # horizontal translation\\n            # composition rule: the translation T_a(t) (a = -X_i S(u)) runs together with the x-translation in the B coordinate that moves with the chart centre;\\n            # generator = translation generator + G o T_a(t)^{-1}, G = d1 * y1 (B coordinate). At the end it is exactly (0, v_i) + lam B(xi + d1 e_x).\\n            Su = self.clk(u, m)[0]\\n            H = 0\\n            for i in range(k):\\n                kind, b, _ = self.pieces[i]\\n                d1 = b[0] if kind == \\\'up\\\' else b[0] - 1.0     # lower triangles were flipped about x1=0.5 in S4\\n                _, yy1 = self.Binv(torch.stack([q1 - self.X[i] * (1 - Su), p1 - self.v[i]], 1) / LAM)\\n                H = H + (-self.X[i] * (p1 - self.v[i]) + L2 * d1 * yy1) * window(p1 - self.v[i], self.band / 2 - 0.4, 0.2)\\n            return H\\n        if m == 6:      # remove the vertical offset\\n            s, rho, _, _, _, c, _ = self.geom(self.s0)\\n            xh1 = self.x0 + math.pi * s * ((c - q1 / LAM) ** 2 - rho ** 2)\\n            x2, _ = self.Binv(z2)\\n            H = 0\\n            for i in range(k):\\n                W = 1\\n                # the gap between neighbouring pieces in a.x (not normalised) is always 2 g0 (axial and diagonal edges alike):\\n                # the transition band sits in the middle of the gap, width tw*g0, leaving (1 - tw/2) g0 on each side.\\n                tw = self.s6_tw\\n                for (a1, a2), cc in self.tri[i]:\\n                    W = W * (1 - sstep((a1 * xh1 + a2 * x2 - cc - (1 - tw / 2) * self.g0) / (tw * self.g0))[0])\\n                H = H + self.v[i] * q1 * W\\n            return H\\n        raise ValueError(m)\\n\\n    def H(self, Q, P, t):\\n        y = torch.cat([Q, P], 1)\\n        t = float(t)\\n        m = 0\\n        while m < 7 and t >= self.tb[m + 1]:\\n            m += 1\\n        L = self.tb[m + 1] - self.tb[m]\\n        u = (t - self.tb[m]) / L\\n        _, dS = self.clk(u, m)\\n        return dS / L * self.seg_H(m, y, u)\\n\\n\\ndef field(T, y, t):\\n    y = y.detach().requires_grad_(True)\\n    h = T.H(y[:, :2], y[:, 2:], t)\\n    g, = torch.autograd.grad(h.sum(), y)\\n    return torch.cat([g[:, 2:], -g[:, :2]], 1)\\n\\n\\ndef rk4(T, y, N, t0=0.0, t1=1.0, record=None):\\n    h = (t1 - t0) / N\\n    for n in range(N):\\n        t = t0 + n * h\\n        k1 = field(T, y, t); k2 = field(T, y + h / 2 * k1, t + h / 2)\\n        k3 = field(T, y + h / 2 * k2, t + h / 2); k4 = field(T, y + h * k3, t + h)\\n        y = (y + h / 6 * (k1 + 2 * k2 + 2 * k3 + k4)).detach()\\n        if record is not None:\\n            for b in T.tb[1:]:\\n                if t < b <= t + h + 1e-15:\\n                    record.append(y.clone())\\n    return y\\n\\n\\n# ---- sw_pipe.py ----\\n"""SW-1: branch-free time-dependent Hamiltonian for the sheared-window k = 10 packing at A = 19/6 * L.\\nSubclass of toric4d.Toric (same strip charts B_s, keyhole kh1/kh2, wrap_K).\\n\\nItems (ball i -> item):  0 C_Y, 1 W1, 2 W2, 3 T3, 4 T4, 5 T5, 6 T6, 7 W7, 8 W8, 9 C_X.\\n * C_Y, W1 (toric, s < -7/6 L): z1 = keyholed u (x1 = m\\\'), z2 = keyholed zeta pushed radially\\n   (C_Y: x2 -> K + x2;  W1: (x2, y2) -> (P_top - x2, 1 - y2)), z2 handled inside the ball\\\'s p1 band.\\n * W8, C_X (toric, s > 7/6 L): z2 = zeta untouched (W8 rotated by -2 pi y1), x1 = P8 + m\\\' + nu / K + m\\\'.\\n * middle items W2 T3 T4 T5 T6 W7: P form  s = P + m\\\' + c nu,  W = z2 e^{2 pi i y1} = W0 + zeta e^{-2 pi i c Theta}\\n   with G = 0, produced in the z1 strip only (z1-only final wrap: no branch cut), then S-invariant reduced flows\\n   in the final chart (x = mu2, phi = arg(z1 z2)/2pi):\\n     Ra  sector lift of the P disc into a far stadium (Lagrangian cotangent lift, inside the item\\\'s 90 deg sector),\\n     Rb  cotangent lift (about x = X_c) of the Lagrangian isotopy (1-t) id + t Phi_s of one circle diffeomorphism\\n         Phi_s per level: affine (slope 1/r = E\\\'/E) on every far interval, gaps compressed (global, no item windows).\\nSegments (index: name):\\n 0 kick, 1 kh1, 2 kh2, 3 unwrap, 4 strip, 5 move (+ C_Y/W1 z2 rewrap), 6 deoff, 7 trans, 8 unD, 9 wrap,\\n 9 deoff2 (C_Y, W1 leave their bands), 10 wrap, 11 Ra, 12 Rb.\\n"""\\nimport math\\nimport torch\\n\\nPI = math.pi\\nKAP = 2 * (1 - PI / 4)\\n\\n\\n# ------------------------------------------------------------------ smooth helpers\\ndef S7(r):\\n    r = r.clamp(0.0, 1.0)\\n    return r ** 4 * (35 - 84 * r + 70 * r ** 2 - 20 * r ** 3)\\n\\n\\ndef IS7(r):\\n    rc = r.clamp(0.0, 1.0)\\n    return rc ** 5 * (7 - 14 * rc + 10 * rc ** 2 - 2.5 * rc ** 3) + (r - 1).clamp(min=0.0)\\n\\n\\ndef hsym(y, w):\\n    return w * IS7((y + w / 2) / w)\\n\\n\\ndef sramp(y, tau):\\n    return hsym(y - tau / 2, tau)\\n\\n\\ndef win7(y, half, trans):\\n    """C^3 window: 1 for |y| <= half, 0 for |y| >= half + trans."""\\n    return 1 - S7((y.abs() - half) / trans)\\n\\n\\ndef band7(y, lo, hi, trans):\\n    """C^3 indicator of [lo, hi] with transitions of width trans outside."""\\n    return (1 - S7((lo - y) / trans)) * (1 - S7((y - hi) / trans))\\n\\n\\ndef lens_C(x0, a, R):\\n    """capacity of {|W - W0|^2 < a, |W|^2 < x0}, |W0| = R (lens area / pi)."""\\n    lo, hi = (R - a.sqrt()) ** 2, (R + a.sqrt()) ** 2\\n    xc = torch.minimum(torch.maximum(x0, lo), hi)\\n    r1, r2, d = xc.sqrt(), a.sqrt(), R\\n    c1 = ((d * d + xc - a) / (2 * d * r1)).clamp(-1.0, 1.0)\\n    c2 = ((d * d + a - xc) / (2 * d * r2)).clamp(-1.0, 1.0)\\n    k = ((-d + r1 + r2) * (d + r1 - r2) * (d - r1 + r2) * (d + r1 + r2)).clamp_min(0.0)\\n    return (xc * torch.acos(c1) + a * torch.acos(c2) - 0.5 * k.sqrt()) / PI\\n\\n\\ndef blob_h(x, a, R):\\n    cth = (x + R * R - a) / (2 * R * x.clamp_min(1e-30).sqrt())\\n    return torch.acos(cth.clamp(-1.0, 1.0)) / (2 * PI)\\n\\n\\ndef seg_area(u):\\n    t = torch.acos((1 - u).clamp(-1.0, 1.0))\\n    return 0.5 * (t - torch.sin(t) * torch.cos(t))\\n\\n\\ndef seg_inv(m):\\n    """u in [0,1] with seg_area(u) = m, m in [0, pi/4]: Kepler-type Newton in t (seg = (2t - sin 2t)/4)."""\\n    m = m.clamp(0.0, PI / 4)\\n    t = (6 * m).clamp_min(1e-300) ** (1 / 3) * (2 ** (-1 / 3)) * 1.0\\n    t = torch.minimum(t, torch.full_like(t, PI / 2))\\n    for _ in range(8):\\n        f = (2 * t - torch.sin(2 * t)) / 4 - m\\n        d = (1 - torch.cos(2 * t)) / 2\\n        t = (t - f / d.clamp_min(1e-30)).clamp(0.0, PI / 2)\\n    return 1 - torch.cos(t)\\n\\n\\ndef stadium_w(xp, E, rho, W):\\n    u1 = (xp / rho).clamp(0.0, 1.0); u2 = ((E - xp) / rho).clamp(0.0, 1.0)\\n    return W * (u1 * (2 - u1)).clamp_min(0).sqrt() * (u2 * (2 - u2)).clamp_min(0).sqrt()\\n\\n\\ndef stadium_Minv(m, E, rho, W, a):\\n    """x\\\' in [0,E] whose stadium capacity to the left is m (total a = W (E - KAP rho))."""\\n    e = W * rho * PI / 4\\n    uL = seg_inv(m / (W * rho)); uR = seg_inv((a - m) / (W * rho))\\n    return torch.where(m < e, rho * uL, torch.where(m > a - e, E - rho * uR, rho + (m - e) / W))\\n\\n\\n# ------------------------------------------------------------------ the pipeline\\nMIDDLE = [\\\'W2\\\', \\\'T3\\\', \\\'T4\\\', \\\'T5\\\', \\\'T6\\\', \\\'W7\\\']\\nP0C = {\\\'W2\\\': (-7 / 6, 0.0), \\\'T3\\\': (-7 / 6, 2 / 3), \\\'T4\\\': (-0.5, 1 / 3), \\\'T5\\\': (-0.5, 2 / 3),\\n       \\\'T6\\\': (1 / 6, 1 / 3), \\\'W7\\\': (1 / 6, 1.0)}\\nSECTOR = {\\\'W2\\\': -0.375, \\\'W7\\\': -0.375, \\\'T3\\\': -0.125, \\\'T6\\\': -0.125, \\\'T4\\\': 0.125, \\\'T5\\\': 0.375}\\nBALLS = [\\\'CY\\\', \\\'W1\\\', \\\'W2\\\', \\\'T3\\\', \\\'T4\\\', \\\'T5\\\', \\\'T6\\\', \\\'W7\\\', \\\'W8\\\', \\\'CX\\\']\\nSEGS = [\\\'kick\\\', \\\'kh1\\\', \\\'kh2\\\', \\\'unwrap\\\', \\\'strip\\\', \\\'move\\\', \\\'deoff\\\', \\\'trans\\\', \\\'unD\\\', \\\'deoff2\\\', \\\'wrap\\\', \\\'Ra\\\', \\\'Rb\\\']\\n\\n\\nclass SWPipe(Toric):\\n    def __init__(self, L, DK=4.1e-3, kh=(0.004, 9.0, 1e-4, 0.05, 3e-3), s0=0.001, band=4.4,\\n                 R_W=2.3, X_a=1.4, Ep=5.5, rho_p=0.03, gc_frac=0.15, gfar_frac=0.25, gam_frac=0.25,\\n                 weights=None, clocks=None, kz=0.2, fmin_frac=0.1 / 3, bump_m=0.2, bump_t=0.2, chis_wide=False,\\n                 lam_clk=1.5, beta_clk=0.15, comp=None):\\n        super().__init__(1, g0=0.003, kh=kh, kh_out=(0.004, 0.0), s0=s0, band=band)\\n        self.fmin_frac, self.bump_m, self.bump_t, self.chis_wide = fmin_frac, bump_m, bump_t, chis_wide\\n        self.lam_clk, self.beta_clk, self.comp = lam_clk, beta_clk, comp\\n        self.nit_rb, self.nit_ra = 40, 16\\n        self._init_expclock()\\n        self.L, self.A = L, 19 / 6 * L\\n        self.DK = DK\\n        slack = L - 1 - DK\\n        assert slack > 0\\n        self.tau = slack / 3.5\\n        self.sig = 2 * self.tau\\n        self.sig_c = self.tau / 2\\n        self.kz = kz * L\\n        self.R_W, self.X_a, self.Ep, self.rho_p = R_W, X_a, Ep, rho_p\\n        tau, sig = self.tau, self.sig\\n        # toric / edge items\\n        self.K = self.A - L + self.sig_c\\n        self.P8 = 7 / 6 * L + sig\\n        self.Ptop = 13 / 6 * L - sig\\n        # middle items\\n        self.it = {}\\n        for j, n in enumerate(MIDDLE):\\n            p0, c = P0C[n]\\n            self.it[n] = dict(p=L * p0, c=c, P=L * p0 + sig, alpha=SECTOR[n])\\n        # temporary x1 offsets D (S5) and their removal Delta = D - P (S8); s-windows of S7 are [D, D + 1 + DK]\\n        D = self.K + 1 + DK + 0.15\\n        for j, n in enumerate(MIDDLE):\\n            self.it[n][\\\'D\\\'] = D\\n            self.it[n][\\\'Delta\\\'] = D - self.it[n][\\\'P\\\']\\n            D += (1 + self.it[n][\\\'c\\\']) * (1 + DK) + 0.3\\n        for n in MIDDLE:\\n            a = self.it[n][\\\'alpha\\\']\\n            self.it[n][\\\'W0\\\'] = (R_W * math.cos(2 * PI * a), R_W * math.sin(2 * PI * a))\\n        # balls\\n        self.X = [3.0 * i for i in range(10)]\\n        self.v = [band * (i + 1) for i in range(10)]\\n        # x1 offsets applied in S5\\n        d1 = {\\\'CY\\\': 0.0, \\\'W1\\\': 0.0, \\\'W8\\\': self.P8, \\\'CX\\\': self.K}\\n        for n in MIDDLE:\\n            d1[n] = self.it[n][\\\'D\\\']\\n        self.d1 = [d1[b] for b in BALLS]\\n        # reduced-stage budget: fractions of the minimal slack\\n        self._set_budget(gc_frac, gfar_frac, gam_frac)\\n        self._Om = None\\n        if self.comp == \\\'omega\\\':\\n            self._init_omega()\\n        # segments\\n        self.nseg = len(SEGS)\\n        w = weights or dict(kick=1.0, kh1=1.0, kh2=0.5, unwrap=1.3, strip=1.0, move=1.2, deoff=1.0, trans=1.0,\\n                            unD=1.0, deoff2=1.0, wrap=1.5, Ra=2.5, Rb=2.5)\\n        wl = [w[k] for k in SEGS]\\n        tot = sum(wl)\\n        self.tb = [0.0]\\n        for x in wl:\\n            self.tb.append(self.tb[-1] + x / tot)\\n        ck = clocks or dict(kick=\\\'sin4\\\', kh1=\\\'sin4\\\', kh2=\\\'sin4\\\', unwrap=\\\'sstep\\\', strip=\\\'sin4\\\', move=\\\'sin4\\\',\\n                            deoff=\\\'sin4\\\', trans=\\\'sin4\\\', unD=\\\'sin4\\\', deoff2=\\\'sin4\\\', wrap=\\\'sstep\\\', Ra=\\\'sin4\\\', Rb=\\\'sin4\\\')\\n        self.clock = tuple(ck[k] for k in SEGS)\\n\\n    # ---------------------------------------------------------------- \\\'exp\\\' clock (reduced stages)\\n    def _init_expclock(self):\\n        """S\\\'(u) = b(u) e^{lam u} / F1, b = S7(u/beta) S7((1-u)/beta) (flat top, C^3 ends).  Late-heavy: the Rb drift\\n        decays like 1/(1 + tau (1/r - 1)), so S\\\' ~ e^{lam u} with lam ~ ln(1/r) keeps drift * S\\\' roughly constant."""\\n        # 24-point Gauss-Legendre rule as float literals (the values of numpy.polynomial.legendre.leggauss(24))\\n        xg = [-0.9951872199970213, -0.9747285559713095, -0.9382745520027328, -0.8864155270044011, -0.820001985973903, -0.7401241915785544, -0.6480936519369755, -0.5454214713888396, -0.4337935076260451, -0.3150426796961634, -0.1911188674736163, -0.06405689286260563, 0.06405689286260563, 0.1911188674736163, 0.3150426796961634, 0.4337935076260451, 0.5454214713888396, 0.6480936519369755, 0.7401241915785544, 0.820001985973903, 0.8864155270044011, 0.9382745520027328, 0.9747285559713095, 0.9951872199970213]\\n        wg = [0.012341229799986784, 0.028531388628933684, 0.04427743881741942, 0.059298584915436534, 0.07334648141108027, 0.08619016153195343, 0.09761865210411409, 0.10744427011596573, 0.11550566805372571, 0.12167047292780352, 0.1258374563468285, 0.1279381953467523, 0.1279381953467523, 0.1258374563468285, 0.12167047292780352, 0.11550566805372571, 0.10744427011596573, 0.09761865210411409, 0.08619016153195343, 0.07334648141108027, 0.059298584915436534, 0.04427743881741942, 0.028531388628933684, 0.012341229799986784]\\n        self._glx, self._glw = xg, wg\\n        self._F1 = self._expF(1.0)\\n\\n    def _expf(self, u):\\n        lam, be = self.lam_clk, self.beta_clk\\n        def s7(r):\\n            r = min(max(r, 0.0), 1.0)\\n            return r ** 4 * (35 - 84 * r + 70 * r ** 2 - 20 * r ** 3)\\n        return s7(u / be) * s7((1 - u) / be) * math.exp(lam * u)\\n\\n    def _gl(self, a, b):\\n        if b <= a:\\n            return 0.0\\n        h = 0.5 * (b - a)\\n        tot = 0.0\\n        for x, w in zip(self._glx, self._glw):      # plain left-to-right sum (same doubles as with numpy scalars)\\n            tot = tot + w * self._expf(a + h * (x + 1))\\n        return h * tot\\n\\n    def _expF(self, u):\\n        lam, be = self.lam_clk, self.beta_clk\\n        u = min(max(u, 0.0), 1.0)\\n        tot = self._gl(0.0, min(u, be))\\n        if u > be:\\n            b2 = min(u, 1 - be)\\n            tot += (math.exp(lam * b2) - math.exp(lam * be)) / lam if lam != 0 else (b2 - be)\\n        if u > 1 - be:\\n            tot += self._gl(1 - be, u)\\n        return tot\\n\\n    def clk(self, u, m):\\n        kind = self.clock[m]\\n        if kind == \\\'exp\\\':\\n            u = min(max(float(u), 0.0), 1.0)\\n            return self._expF(u) / self._F1, self._expf(u) / self._F1\\n        return super().clk(u, m)\\n\\n    # ---------------------------------------------------------------- rigid per-level rotation Omega(s)\\n    def _init_omega(self, ng=24001):\\n        """Omega\\\' = -(sum_j W_j^2 c_j\\\') / (sum_j W_j^2 + 1e-8): cancels the common motion of the final window centres\\n        (drift (x - X_c) dG/ds of Rb).  Omega(0) = 0; tabulated, evaluated by cubic Hermite (C^1)."""\\n        smax = 7 / 6 * self.L + 3 * self.tau\\n        s = torch.linspace(-smax, smax, ng).requires_grad_(True)\\n        lay = self.layout(s)\\n        num = torch.zeros(ng); den = torch.full((ng,), 1e-8)\\n        for n in MIDDLE:\\n            c = lay[\\\'phic\\\'][n]\\n            dc, = torch.autograd.grad(c.sum(), s, retain_graph=True)\\n            w = lay[\\\'W\\\'][n].detach() ** 2\\n            num = num + w * dc; den = den + w\\n        dOm = -(num / den).detach()\\n        sd = s.detach()\\n        h = float(sd[1] - sd[0])\\n        Om = torch.cat([torch.zeros(1), torch.cumsum(0.5 * h * (dOm[1:] + dOm[:-1]), 0)])\\n        Om = Om - Om[ng // 2]\\n        self._Om = (sd, Om, dOm, h, -smax)\\n\\n    def Omega(self, s):\\n        sg, Om, dOm, h, s0 = self._Om\\n        u = ((s - s0) / h).clamp(0, len(sg) - 1 - 1e-9)\\n        i = u.detach().floor().long()\\n        t = u - i\\n        y0, y1, d0, d1 = Om[i], Om[i + 1], dOm[i] * h, dOm[i + 1] * h\\n        t2, t3 = t * t, t * t * t\\n        return (2 * t3 - 3 * t2 + 1) * y0 + (t3 - 2 * t2 + t) * d0 + (-2 * t3 + 3 * t2) * y1 + (t3 - t2) * d1\\n\\n    # ---------------------------------------------------------------- window capacities a_j(s) (sw_static)\\n    def a_item(self, n, s):\\n        it = self.it[n]\\n        p, c, tau, sig = it[\\\'p\\\'], it[\\\'c\\\'], self.tau, self.sig\\n        T = s - p\\n        right = sig + 1 + self.DK\\n        if c == 0:\\n            return sramp(right + tau - T, tau) * S7((T - sig / 2) / (sig / 2))\\n        if c == 1:\\n            return sramp(T - sig + tau, tau) * (1 - S7((T - right) / tau))\\n        f1 = sramp(T - sig + tau, tau) / c\\n        f2 = sramp(right + tau - T, tau) / (1 - c)\\n        return torch.minimum(f1, f2) - hsym(-(f1 - f2).abs(), tau)\\n\\n    def live(self, n, s):\\n        """1 on the item\\\'s ball s-range (and its smoothing zone), 0 outside the slot."""\\n        it = self.it[n]\\n        T = s - it[\\\'p\\\']\\n        tau, sig = self.tau, self.sig\\n        right = sig + 1 + self.DK\\n        # ball levels: T in [sig, right]; a > 0 on (sig - tau, right + tau): ramp inside that\\n        return S7((T - (sig - tau / 2)) / (tau / 2)) * (1 - S7((T - right) / (tau / 2)))\\n\\n    # ---------------------------------------------------------------- final windows\\n    def zin(self, s):\\n        return 0.5 * (hsym(s, self.kz) + hsym(-s, self.kz))\\n\\n    def radial(self, s):\\n        x_lo = self.zin(s) - s / 2 + self.g_c\\n        x_hi = self.A / 2 - s / 2\\n        return x_lo, x_hi\\n\\n    def layout(self, s):\\n        """per level: dict with E, x_lo, x_hi, rho_f, widths W_j, centres phic_j, phi_ref, psi_j, delta_j, wfar_j."""\\n        x_lo, x_hi = self.radial(s)\\n        E = x_hi - x_lo\\n        rho_f = self.rho_p * E / self.Ep\\n        Wd = {n: self.a_item(n, s) / (E - KAP * rho_f) for n in MIDDLE}\\n        # sector-order cumulative layout (W2|W7, T3|T6, T4, T5), gaps gam (W_k + W_k+1)/2 + f_min, occupied arc\\n        # centred at phi = 0 (free arc around 1/2); absent items have W = 0 and sit at their cumulative position\\n        sec = [Wd[\\\'W2\\\'] + Wd[\\\'W7\\\'], Wd[\\\'T3\\\'] + Wd[\\\'T6\\\'], Wd[\\\'T4\\\'], Wd[\\\'T5\\\']]\\n        fmin = self.f_min\\n        gaps = [self.gam * (sec[k] + sec[k + 1]) / 2 + fmin for k in range(3)]\\n        tot = sec[0] + sec[1] + sec[2] + sec[3] + gaps[0] + gaps[1] + gaps[2]\\n        cen, lo = [], -tot / 2\\n        for k in range(4):\\n            cen.append(lo + sec[k] / 2)\\n            lo = lo + sec[k] + (gaps[k] if k < 3 else 0.0)\\n        phif = {\\\'W2\\\': cen[0], \\\'W7\\\': cen[0], \\\'T3\\\': cen[1], \\\'T6\\\': cen[1], \\\'T4\\\': cen[2], \\\'T5\\\': cen[3]}\\n        if getattr(self, \\\'_Om\\\', None) is not None:\\n            Om = self.Omega(s)\\n            phif = {k: v + Om for k, v in phif.items()}\\n        Sccw, Scw, phi_ref = tot / 2, tot / 2, torch.zeros_like(s)\\n        r = E / self.Ep\\n        psi = {n: phif[n] * r for n in MIDDLE}\\n        delta = {n: psi[n] - self.it[n][\\\'alpha\\\'] for n in MIDDLE}\\n        wfar = {n: Wd[n] * r for n in MIDDLE}\\n        Xc = (x_lo - self.X_a * r) / (1 - r)\\n        return dict(E=E, x_lo=x_lo, x_hi=x_hi, rho_f=rho_f, W=Wd, phic=phif, Sccw=Sccw, Scw=Scw, phi_ref=phi_ref,\\n                    psi=psi, delta=delta, wfar=wfar, r=r, Xc=Xc, lam=torch.log(1 / r))\\n\\n    def _set_budget(self, gc_frac, gfar_frac, gam_frac):\\n        """minimal relative slack 1 - sum W over |s| < 7/6 L with g_c = gam = 0, then split it."""\\n        self.g_c, self.gam, self.f_min = 0.0, 0.0, 0.0\\n        s = torch.linspace(-7 / 6 * self.L, 7 / 6 * self.L, 40001)\\n        lay = self.layout(s)\\n        tot = sum(lay[\\\'W\\\'][n] for n in MIDDLE)\\n        free = 1 - tot\\n        mfree = float(free.min())\\n        E = lay[\\\'E\\\']\\n        # fractions of the minimal free angle: g_c costs ~g_c/E of angle, gamma <= gamma * sum W, 3 f_min, gfar\\n        self.g_c = gc_frac * mfree * float(E.min())\\n        self.gam = gam_frac * mfree\\n        self.f_min = self.fmin_frac * mfree\\n        self.g_far = gfar_frac * mfree\\n        lay = self.layout(s)\\n        arc = lay[\\\'Sccw\\\'] + lay[\\\'Scw\\\']\\n        self.min_free_angle = float((1 - arc).min())\\n        self.budget = dict(mfree0=mfree, g_c=self.g_c, gam=self.gam, f_min=self.f_min, g_far=self.g_far,\\n                           min_free_angle_after=self.min_free_angle, rho_f_max=float((self.rho_p * E / self.Ep).max()))\\n        assert self.min_free_angle > self.g_far, self.budget\\n\\n    # ---------------------------------------------------------------- static (analytic) reduced endpoint, middle item\\n    def Ra_target(self, n, s):\\n        """far stadium of item n at level s: (E\\\', rho\\\', width W\\\')."""\\n        lay = self.layout(s)\\n        return lay[\\\'wfar\\\'][n]\\n\\n    def Ra_Z(self, n, s, x0, a=None):\\n        """radial endpoint map of the sector lift: blob (W0, a) -> far stadium [X_a, X_a + E\\\']."""\\n        if a is None:\\n            a = self.a_item(n, s)\\n        Wf = self.Ra_target(n, s)\\n        Cx = lens_C(x0, a, self.R_W)\\n        return self.X_a + stadium_Minv(Cx, torch.full_like(Cx, self.Ep), self.rho_p, Wf, a)\\n\\n    def static_reduced(self, n, s, W):\\n        """(s, W = W0 + zeta\\\') -> final (x, phi) of item n (composition Ra, Rb1, Rb2)."""\\n        it = self.it[n]\\n        a = self.a_item(n, s)\\n        x0 = W.abs() ** 2\\n        ph0 = torch.angle(W) / (2 * PI)\\n        dph = torch.remainder(ph0 - it[\\\'alpha\\\'] + 0.5, 1.0) - 0.5\\n        Z = self.Ra_Z(n, s, x0, a)\\n        Wf = self.Ra_target(n, s)\\n        wt = stadium_w(Z - self.X_a, torch.full_like(Z, self.Ep), self.rho_p, Wf)\\n        hb = blob_h(x0, a, self.R_W)\\n        phi1 = it[\\\'alpha\\\'] + dph * wt / (2 * hb)\\n        cm = self.circle_map(s)\\n        base = cm[\\\'Ilo\\\'][0]\\n        p0 = base + torch.remainder(phi1 - base, 1.0)\\n        phi3, rho = self.Phi_f(cm, p0)\\n        x3 = cm[\\\'lay\\\'][\\\'Xc\\\'] + (Z - cm[\\\'lay\\\'][\\\'Xc\\\']) / rho\\n        return x3, phi3\\n\\n    def final_window_margin(self, n, s, x, phi):\\n        lay = self.layout(s)\\n        E, rho_f = lay[\\\'E\\\'], lay[\\\'rho_f\\\']\\n        wt = stadium_w(x - lay[\\\'x_lo\\\'], E, rho_f, lay[\\\'W\\\'][n])\\n        dphi = (torch.remainder(phi - lay[\\\'phic\\\'][n] + 0.5, 1.0) - 0.5).abs()\\n        return torch.minimum(wt / 2 - dphi, torch.minimum(x - lay[\\\'x_lo\\\'], lay[\\\'x_hi\\\'] - x))\\n\\n    # ---------------------------------------------------------------- helpers in R^4\\n    @staticmethod\\n    def reduced_coords(y):\\n        q1, q2, p1, p2 = y.unbind(1)\\n        mu1, mu2 = q1 ** 2 + p1 ** 2, q2 ** 2 + p2 ** 2\\n        phi = torch.atan2(q1 * p2 + p1 * q2, q1 * q2 - p1 * p2) / (2 * PI)\\n        return mu1 - mu2, mu2, phi\\n\\n    def bwin(self, p1, i):\\n        return window(p1 - self.v[i], self.band / 2 - 0.4, 0.2)\\n\\n    def xh1(self, q1):\\n        s, rho, _, _, _, c, _ = self.geom(self.s0)\\n        return self.x0 + PI * s * ((c - q1 / LAM) ** 2 - rho ** 2)\\n\\n    # ---------------------------------------------------------------- segment Hamiltonians (per unit clock S)\\n    def seg_H(self, m, y, u):\\n        q1, q2, p1, p2 = y.unbind(1)\\n        z2w = torch.stack([q2, p2], 1) / LAM\\n        L2 = LAM ** 2\\n        name = SEGS[m]\\n        S, dS = self.clk(u, m)\\n        if name == \\\'kick\\\':\\n            H = 0\\n            for i in range(10):\\n                H = H + (-self.v[i]) * (q1 - self.X[i]) * window(q1 - self.X[i], 1.2, 0.5)\\n            return H\\n        if name in (\\\'kh1\\\', \\\'kh2\\\'):\\n            prim = self.kh1 if name == \\\'kh1\\\' else self.kh2\\n            H = 0\\n            for i in range(10):\\n                z1 = torch.stack([q1 - self.X[i], p1 - self.v[i]], 1) / LAM\\n                H = H + L2 * prim(z1) * self.bwin(p1, i)\\n            for i in (0, 1):\\n                H = H + L2 * prim(z2w) * self.bwin(p1, i)\\n            return H\\n        if name == \\\'unwrap\\\':\\n            s, dsds = self.sched(float(S))\\n            H = 0\\n            for i in range(10):\\n                z1 = torch.stack([q1 - self.X[i], p1 - self.v[i]], 1) / LAM\\n                H = H + L2 * self.wrap_K(z1, s) * self.bwin(p1, i)\\n            for i in (0, 1):\\n                H = H + L2 * self.wrap_K(z2w, s) * self.bwin(p1, i)\\n            return dsds * H\\n        if name == \\\'strip\\\':\\n            H = 0\\n            mu2 = q2 ** 2 + p2 ** 2\\n            for i, n in enumerate(BALLS):\\n                if n == \\\'CX\\\':\\n                    continue\\n                if n == \\\'CY\\\':\\n                    _, yy2 = self.Binv(z2w)\\n                    G = self.K * yy2\\n                elif n == \\\'W1\\\':\\n                    x2, yy2 = self.Binv(z2w)\\n                    G = (PI / 2) * ((x2 - self.Ptop / 2) ** 2 + (yy2 - 0.5) ** 2)\\n                else:\\n                    c = 0.0 if n == \\\'W8\\\' else self.it[n][\\\'c\\\']\\n                    _, yy1 = self.Binv(torch.stack([q1 - self.X[i], p1 - self.v[i]], 1) / LAM)\\n                    # centred twist: rotation angle -2 pi (1+c)(y1 - 1/2), |angle| <= pi (1+c); the constant\\n                    # offset rotation of zeta by pi (1+c) maps the round ball to itself\\n                    G = (1 + c) * (yy1 - 0.5) * mu2\\n                H = H + L2 * G * self.bwin(p1, i)\\n            return H\\n        if name == \\\'move\\\':\\n            H = 0\\n            s, dsds = self.sched(1 - float(S))\\n            for i, n in enumerate(BALLS):\\n                _, yy1 = self.Binv(torch.stack([q1 - self.X[i] * (1 - S), p1 - self.v[i]], 1) / LAM)\\n                Hi = -self.X[i] * (p1 - self.v[i]) + L2 * self.d1[i] * yy1\\n                if n in (\\\'CY\\\', \\\'W1\\\'):\\n                    Hi = Hi + L2 * (-dsds) * self.wrap_K(z2w, s)\\n                H = H + Hi * self.bwin(p1, i)\\n            return H\\n        if name == \\\'deoff\\\':\\n            xh = self.xh1(q1)\\n            mu2 = q2 ** 2 + p2 ** 2\\n            # xh1 = x1 - s0 (p1 - v)^2 >= x1 - 8e-4: lower window edges sit 1e-3 below the item\\\'s x1 range\\n            tr = 0.25 * self.tau\\n            e = 1e-3\\n            H = 0\\n            for i, n in enumerate(BALLS):\\n                if n in (\\\'CY\\\', \\\'W1\\\'):\\n                    continue           # moved later (deoff2), after the middle items\\\' strip stages\\n                elif n == \\\'W8\\\':\\n                    Wi = band7(xh, self.P8 - 0.05, self.P8 + 1 + self.DK, tr)\\n                elif n == \\\'CX\\\':\\n                    Wi = band7(xh, self.K - e, self.K + 1 + self.DK, tr)\\n                else:\\n                    D, c = self.it[n][\\\'D\\\'], self.it[n][\\\'c\\\']\\n                    Wi = band7(xh, D, D + (1 + c) * (1 + self.DK), 0.05)\\n                H = H + self.v[i] * q1 * Wi\\n            return H\\n        if name == \\\'trans\\\':\\n            pw = win7(p1, 1.2, 0.6)\\n            x1, yy1 = self.Binv(torch.stack([q1, p1], 1) / LAM)\\n            st = x1 - (q2 ** 2 + p2 ** 2)\\n            H = 0\\n            for n in MIDDLE:\\n                D = self.it[n][\\\'D\\\']\\n                chi = band7(st, D - 0.04, D + 1 + self.DK + 0.04, 0.04) * pw\\n                W0q, W0p = self.it[n][\\\'W0\\\']\\n                ang = -2 * PI * yy1\\n                bq = W0q * torch.cos(ang) - W0p * torch.sin(ang)\\n                bp = W0q * torch.sin(ang) + W0p * torch.cos(ang)\\n                H = H + chi * (bq * p2 - bp * q2)\\n            return H\\n        if name == \\\'unD\\\':\\n            pw = win7(p1, 1.2, 0.6)\\n            x1, yy1 = self.Binv(torch.stack([q1, p1], 1) / LAM)\\n            st = x1 - (q2 ** 2 + p2 ** 2)\\n            ang = 2 * PI * yy1\\n            Wq = q2 * torch.cos(ang) - p2 * torch.sin(ang)\\n            Wp = q2 * torch.sin(ang) + p2 * torch.cos(ang)\\n            H = 0\\n            for n in MIDDLE:\\n                it = self.it[n]\\n                dW = ((Wq - it[\\\'W0\\\'][0]) ** 2 + (Wp - it[\\\'W0\\\'][1]) ** 2).sqrt()\\n                chiW = win7(dW, 1.08, 0.08)\\n                sf = st - it[\\\'Delta\\\'] * (1 - S)\\n                chis = band7(sf, it[\\\'p\\\'] - 0.05, it[\\\'p\\\'] + self.L + 0.05, 0.1) * pw\\n                H = H - L2 * it[\\\'Delta\\\'] * yy1 * chiW * chis\\n            return H\\n        if name == \\\'deoff2\\\':\\n            # C_Y, W1 leave their bands; static (flow-invariant) windows in xh1, |z2|^2 and sh = xh1 - |z2|^2:\\n            # W1 / C_Y have sh <= -7/6 L - 1.5 tau, every middle item has sh >= -7/6 L + 2 tau - 8e-4\\n            xh = self.xh1(q1)\\n            mu2 = q2 ** 2 + p2 ** 2\\n            sh = xh - mu2\\n            tr = 0.25 * self.tau\\n            # W1 has BOTH factors keyholed, so its sh reaches -7/6 L - 1.5 tau + DK (measured -0.94 tau at\\n            # L = 1.021); the old switch [-1.5 tau, -0.5 tau] cut through W1.  Switch inside the true gap\\n            # [-7/6 L - 1.5 tau + DK, -7/6 L + 2 tau - 8e-4] with 5 % margins.\\n            g = 3.5 * self.tau - self.DK - 8e-4\\n            assert g > 0, \\\'deoff2: W1 / middle-item sh ranges overlap\\\'\\n            a0 = -7 / 6 * self.L - 1.5 * self.tau + self.DK + 0.05 * g\\n            sw = 1 - S7((sh - a0) / (0.9 * g))\\n            H = 0\\n            for i, n in ((0, \\\'CY\\\'), (1, \\\'W1\\\')):\\n                if n == \\\'CY\\\':\\n                    Wi = band7(xh, -0.05, 1 + self.DK, 0.02) * band7(mu2, self.K, self.K + 1 + self.DK, tr)\\n                else:\\n                    Wi = band7(xh, -0.05, 1 + self.DK, 0.02) * band7(mu2, self.Ptop - 1 - self.DK, self.Ptop, tr)\\n                H = H + self.v[i] * q1 * Wi * sw\\n            return H\\n        if name == \\\'wrap\\\':\\n            s, dsds = self.sched(1 - float(S))\\n            return -dsds * L2 * self.wrap_K(torch.stack([q1, p1], 1) / LAM, s)\\n        # ---------------- S-invariant reduced stages: H = pi * H_red(s, x, phi)\\n        s, x, phi = self.reduced_coords(y)\\n        if self.chis_wide:\\n            # middle items: -7/6 L + 2 tau <= s <= L/6 + 2 tau + 1 + DK;  lattice items: s <= -7/6 L - 1.5 tau,\\n            # s >= 7/6 L + 2 tau.  Plateau 0.1 tau outside the middle range, transition 3 tau.\\n            # bottom gap: W1 (z1 and z2 keyholed) s <= -7/6 L - 1.5 tau + DK,  W2 s >= -7/6 L + 2 tau  (width 3.5 tau - DK)\\n            # top gap:    W7 s <= 7/6 L - 1.5 tau,  W8 s >= 7/6 L + 2 tau  (width 3.5 tau)\\n            tau, L = self.tau, self.L\\n            gb = 3.5 * tau - self.DK\\n            assert gb > 0, \\\'W1 / W2 s-ranges overlap (DK too large for this L)\\\'\\n            lo, hi = -7 / 6 * L + 2 * tau - 0.05 * gb, 7 / 6 * L - 1.5 * tau + 0.05 * 3.5 * tau\\n            ltr, htr = 0.85 * gb, 0.85 * 3.5 * tau\\n            chis = (1 - S7((lo - s) / ltr)) * (1 - S7((s - hi) / htr))\\n        else:\\n            chis = band7(s, -7 / 6 * self.L + 0.5 * self.sig, 7 / 6 * self.L - 0.5 * (self.L - 1 - self.DK - self.sig),\\n                         0.2 * self.sig)\\n        # layout quantities are only meaningful for |s| < 7/6 L; clamp so that H stays finite elsewhere (chis = 0 there)\\n        smax = 7 / 6 * self.L + (2 * self.tau if self.chis_wide else 0.0)\\n        s = s.clamp(-smax, smax)\\n        x = x.clamp(1e-9, 60.0)\\n        if name == \\\'Ra\\\':\\n            return PI * chis * self.Ra_H(s, x, phi, float(S))\\n        if name == \\\'Rb\\\':\\n            return PI * chis * self.Rb_H(s, x, phi, float(S))\\n        raise ValueError(name)\\n\\n    # ---- Ra: sector lift, Lagrangian interpolation z_tau = (1 - tau) x0 + tau Z(x0)\\n    def Ra_H(self, s, x, phi, tau):\\n        H = torch.zeros_like(s)\\n        for sec, names in ((-0.375, (\\\'W2\\\', \\\'W7\\\')), (-0.125, (\\\'T3\\\', \\\'T6\\\')), (0.125, (\\\'T4\\\',)), (0.375, (\\\'T5\\\',))):\\n            dph = torch.remainder(phi - sec + 0.5, 1.0) - 0.5\\n            chi = win7(dph, 0.105, 0.015)\\n            for n in names:\\n                lv = self.live(n, s)\\n                sel = (chi > 0) & (lv > 0)\\n                if not bool(sel.any()):\\n                    continue\\n                V = torch.zeros_like(s)\\n                Vs = self._Ra_V(n, s[sel], x[sel], tau)\\n                V = V.index_put((sel.nonzero(as_tuple=True)[0],), Vs)\\n                H = H + dph * V * chi * lv\\n        return H\\n\\n    def _Ra_V(self, n, s, x, tau):\\n        a = self.a_item(n, s).clamp_min(1e-12)\\n        lo, hi = (self.R_W - a.sqrt()) ** 2, (self.R_W + a.sqrt()) ** 2\\n        with torch.no_grad():\\n            sd, xd, ad = s.detach(), x.detach(), a.detach()\\n            lod, hid = lo.detach(), hi.detach()\\n            x0 = xd.clone().clamp(lod, hid)\\n            blo, bhi = lod.clone(), hid.clone()\\n            Wf = self.Ra_target(n, sd)\\n            Epf = torch.full_like(xd, self.Ep)\\n            for _ in range(self.nit_ra):\\n                Z = self.Ra_Z(n, sd, x0, ad)\\n                f = (1 - tau) * x0 + tau * Z - xd\\n                blo = torch.where(f < 0, x0, blo); bhi = torch.where(f > 0, x0, bhi)\\n                bisect = 0.5 * (blo + bhi)\\n                # analytic Z\\\' = 2 h(x0) / w_t(Z) (cotangent lift of the vertical fibration)\\n                wt = stadium_w(Z - self.X_a, Epf, self.rho_p, Wf).clamp_min(1e-12)\\n                Zp = 2 * blob_h(x0, ad, self.R_W) / wt\\n                d = (1 - tau) + tau * Zp\\n                x1 = x0 - f / d.clamp_min(1e-12)\\n                ok = (x1 > blo) & (x1 < bhi) & torch.isfinite(x1)\\n                x0 = torch.where(ok, x1, bisect)\\n            # guaranteed tail.  Newton steps near the blob\\\'s radial ends (Z\\\' = 2h/w_t ~ 0/0) are often\\n            # rejected, leaving ~0.3 % of trajectory points unconverged (|f| up to 7e-3) -> non-smooth field and\\n            # N-dependent RK4 outliers.  Pure bisection on the unconverged subset until |f| < 1e-13.\\n            Z = self.Ra_Z(n, sd, x0, ad)\\n            f = (1 - tau) * x0 + tau * Z - xd\\n            bad = (f.abs() > 1e-13 * (1 + xd.abs())) | ~torch.isfinite(f)\\n            if bool(bad.any()):\\n                ii = bad.nonzero(as_tuple=True)[0]\\n                lo_, hi_ = blo[ii], bhi[ii]\\n                f_lo = (1 - tau) * lo_ + tau * self.Ra_Z(n, sd[ii], lo_, ad[ii]) - xd[ii]\\n                for _ in range(64):\\n                    mid = 0.5 * (lo_ + hi_)\\n                    fm = (1 - tau) * mid + tau * self.Ra_Z(n, sd[ii], mid, ad[ii]) - xd[ii]\\n                    left = (fm > 0) == (f_lo > 0)\\n                    lo_ = torch.where(left, mid, lo_); f_lo = torch.where(left, fm, f_lo)\\n                    hi_ = torch.where(left, hi_, mid)\\n                x0 = x0.index_put((ii,), 0.5 * (lo_ + hi_))\\n        x0 = x0.detach()\\n        for _ in range(2):\\n            Z = self.Ra_Z(n, s, x0, a)\\n            f = (1 - tau) * x0 + tau * Z - x\\n            xg = x0.detach().requires_grad_(True)\\n            Zg, = torch.autograd.grad(self.Ra_Z(n, s.detach(), xg, a.detach()).sum(), xg)\\n            x0 = x0 - f / ((1 - tau) + tau * Zg)\\n        return self.Ra_Z(n, s, x0, a) - x0\\n\\n    # ---- Rb: cotangent lift of a Lagrangian isotopy of ONE circle diffeomorphism Phi_s per level (no item windows)\\n    SECTORS = ((\\\'W2\\\', \\\'W7\\\'), (\\\'T3\\\', \\\'T6\\\'), (\\\'T4\\\',), (\\\'T5\\\',))\\n\\n    def circle_map(self, s):\\n        """per level: far intervals I_k (at the sector centres), final intervals F_k, gap bump data.\\n        Phi_f(phi0) = F_0.lo + int_{I_0.lo}^{phi0} rho,  rho = 1/r except a C^3 plateau c_k inside each gap\\n        (margin m_k = t_k = 0.2 r f_k from the gap ends) so that every gap is mapped onto its final gap."""\\n        lay = self.layout(s)\\n        r = lay[\\\'r\\\']\\n        Wk, wf, cf, al = [], [], [], []\\n        for names in self.SECTORS:\\n            if len(names) == 2:\\n                a, b = names\\n                W = lay[\\\'W\\\'][a] + lay[\\\'W\\\'][b]\\n                c = torch.where(s < 0, lay[\\\'phic\\\'][a], lay[\\\'phic\\\'][b])\\n            else:\\n                W = lay[\\\'W\\\'][names[0]]\\n                c = lay[\\\'phic\\\'][names[0]]\\n            Wk.append(W); wf.append(W * r); cf.append(c); al.append(SECTOR[names[0]])\\n        Ilo = [al[k] - wf[k] / 2 for k in range(4)]\\n        Ihi = [al[k] + wf[k] / 2 for k in range(4)]\\n        Flo = [cf[k] - Wk[k] / 2 for k in range(4)]\\n        Fhi = [cf[k] + Wk[k] / 2 for k in range(4)]\\n        gaps = []\\n        for k in range(4):\\n            k2 = (k + 1) % 4\\n            add = 1.0 if k == 3 else 0.0\\n            g_lo, g_hi = Ihi[k], Ilo[k2] + add\\n            fg = Flo[k2] + add - Fhi[k]\\n            gl = g_hi - g_lo\\n            m = self.bump_m * r * fg\\n            t = self.bump_t * r * fg\\n            ib = gl - 2 * m - t\\n            ck = 1 / r + (fg - gl / r) / ib\\n            gaps.append(dict(lo=g_lo, hi=g_hi, m=m, t=t, c=ck, ib=ib))\\n        return dict(r=r, Ilo=Ilo, Flo=Flo, gaps=gaps, lay=lay)\\n\\n    @staticmethod\\n    def _sub_cm(cm, ii):\\n        def sub(v):\\n            return v[ii] if (torch.is_tensor(v) and v.dim() > 0) else v\\n        out = dict(cm)\\n        out[\\\'r\\\'] = sub(cm[\\\'r\\\'])\\n        out[\\\'Ilo\\\'] = [sub(v) for v in cm[\\\'Ilo\\\']]\\n        out[\\\'Flo\\\'] = [sub(v) for v in cm[\\\'Flo\\\']]\\n        out[\\\'gaps\\\'] = [{k: sub(v) for k, v in g.items()} for g in cm[\\\'gaps\\\']]\\n        return out\\n\\n    @staticmethod\\n    def _bump_cum(phi, lo, hi, m, t):\\n        """int_{-inf}^{phi} b, b = C^3 plateau: 0 outside [lo+m, hi-m], 1 on [lo+m+t, hi-m-t]."""\\n        a1, a2 = lo + m, hi - m\\n        up = t * IS7((phi - a1) / t)\\n        dn = t * IS7((phi - (a2 - t)) / t)\\n        return up - dn\\n\\n    @staticmethod\\n    def _bump(phi, lo, hi, m, t):\\n        a1, a2 = lo + m, hi - m\\n        return S7((phi - a1) / t) - S7((phi - (a2 - t)) / t)\\n\\n    def Phi_f(self, cm, phi0):\\n        """phi0 lifted into [I_0.lo, I_0.lo + 1); returns (Phi_f(phi0), rho(phi0))."""\\n        r = cm[\\\'r\\\']\\n        base = cm[\\\'Ilo\\\'][0]\\n        val = cm[\\\'Flo\\\'][0] + (phi0 - base) / r\\n        rho = torch.ones_like(phi0) / r\\n        for g in cm[\\\'gaps\\\']:\\n            cb = self._bump_cum(phi0, g[\\\'lo\\\'], g[\\\'hi\\\'], g[\\\'m\\\'], g[\\\'t\\\']) - self._bump_cum(base, g[\\\'lo\\\'], g[\\\'hi\\\'], g[\\\'m\\\'], g[\\\'t\\\'])\\n            val = val + (g[\\\'c\\\'] - 1 / r) * cb\\n            rho = rho + (g[\\\'c\\\'] - 1 / r) * self._bump(phi0, g[\\\'lo\\\'], g[\\\'hi\\\'], g[\\\'m\\\'], g[\\\'t\\\'])\\n        return val, rho\\n\\n    def Rb_H(self, s, x, phi, tau):\\n        cm = self.circle_map(s)\\n        base = cm[\\\'Ilo\\\'][0]\\n        Xc = cm[\\\'lay\\\'][\\\'Xc\\\']\\n        with torch.no_grad():\\n            cmd = {k: v for k, v in cm.items()}\\n            cmd[\\\'gaps\\\'] = [{kk: (vv.detach() if torch.is_tensor(vv) else vv) for kk, vv in g.items()} for g in cm[\\\'gaps\\\']]\\n            cmd[\\\'Ilo\\\'] = [v.detach() if torch.is_tensor(v) else v for v in cm[\\\'Ilo\\\']]\\n            cmd[\\\'Flo\\\'] = [v.detach() for v in cm[\\\'Flo\\\']]\\n            cmd[\\\'r\\\'] = cm[\\\'r\\\'].detach()\\n            bd = cmd[\\\'Ilo\\\'][0]\\n            Phb = (1 - tau) * bd + tau * self.Phi_f(cmd, torch.as_tensor(bd) + 0 * phi)[0]\\n            target = Phb + torch.remainder(phi.detach() - Phb, 1.0)\\n            lo = torch.as_tensor(bd) + 0 * phi\\n            hi = lo + 1.0\\n            p0 = lo + (target - Phb)       # identity-ish initial guess\\n            p0 = p0.clamp(lo, hi)\\n            for _ in range(self.nit_rb):\\n                v, rh = self.Phi_f(cmd, p0)\\n                f = (1 - tau) * p0 + tau * v - target\\n                lo = torch.where(f < 0, p0, lo); hi = torch.where(f > 0, p0, hi)\\n                p1 = p0 - f / ((1 - tau) + tau * rh)\\n                ok = (p1 > lo) & (p1 < hi) & torch.isfinite(p1)\\n                p0 = torch.where(ok, p1, 0.5 * (lo + hi))\\n            # guaranteed bisection tail on unconverged points (same reason as in Ra)\\n            v, rh = self.Phi_f(cmd, p0)\\n            f = (1 - tau) * p0 + tau * v - target\\n            bad = (f.abs() > 1e-13) | ~torch.isfinite(f)\\n            if bool(bad.any()):\\n                ii = bad.nonzero(as_tuple=True)[0]\\n                cms = self._sub_cm(cmd, ii)\\n                lo_, hi_, tg = lo[ii], hi[ii], target[ii]\\n                for _ in range(64):\\n                    mid = 0.5 * (lo_ + hi_)\\n                    fm = (1 - tau) * mid + tau * self.Phi_f(cms, mid)[0] - tg\\n                    lo_ = torch.where(fm < 0, mid, lo_); hi_ = torch.where(fm < 0, hi_, mid)\\n                p0 = p0.index_put((ii,), 0.5 * (lo_ + hi_))\\n            tgt0 = target\\n        p0 = p0.detach()\\n        # differentiable Newton steps (gradient w.r.t. phi and s through the implicit function)\\n        target = phi + (tgt0 - phi.detach())\\n        for _ in range(2):\\n            v, rh = self.Phi_f(cm, p0)\\n            p0 = p0 - ((1 - tau) * p0 + tau * v - target) / ((1 - tau) + tau * rh)\\n        v, _ = self.Phi_f(cm, p0)\\n        G = -(v - p0)\\n        return (x - Xc) * G\\n\\n    # ---------------------------------------------------------------- time dependence\\n    def H(self, Q, P, t):\\n        y = torch.cat([Q, P], 1)\\n        t = float(t)\\n        m = 0\\n        while m < self.nseg - 1 and t >= self.tb[m + 1]:\\n            m += 1\\n        Ls = self.tb[m + 1] - self.tb[m]\\n        u = (t - self.tb[m]) / Ls\\n        _, dS = self.clk(u, m)\\n        if dS == 0.0:\\n            return 0.0 * y[:, 0]\\n        return dS / Ls * self.seg_H(m, y, u)\\n\\n\\n# ---- sheared-window pipeline ----\\n"""SWPipe2: SWPipe2 = sw_pipe.SWPipe (k = 10 sheared-window pipeline, A = 19/6 L) with\\n (1) every small constant tied to the scale parameters (tau, DK, s0) instead of fixed numbers (deoff / deoff2 edges),\\n     and build-time inequality checks (check_inequalities, raises ValueError with the violated inequality);\\n (2) fast reduced stages Ra / Rb: one layout evaluation per call, all six middle items solved in one vectorised\\n     root-find, stadium caps evaluated only where needed, closed-form inverse of the Rb circle map on the item\\n     intervals; work restricted to the support of the s cut-off;\\n (3) root-finders with a guaranteed tolerance and ONE implicit-function step that carries the gradient\\n     (no autograd through solver iterations);\\n (4) Omega(s) evaluated by a C^4 quintic B-spline (was C^1 cubic Hermite).\\nThe time-1 map for the round-13 parameters is the same as sw_pipe.SWPipe up to the Omega interpolant and the\\ndeoff lower edges (om_interp=\\\'hermite\\\', compat13=True reproduce the round-13 Hamiltonian to rounding).\\n"""\\nimport math\\nimport torch\\n\\n_P6C = [P0C[n] for n in MIDDLE]\\n\\n\\ndef seg_inv2(m):\\n    """u in [0,1] with seg_area(u) = m (m in [0, pi/4]).  Value: Newton in t (seg = (2t - sin 2t)/4, convex, start\\n    below the root => monotone after the first step); gradient: one implicit step, du/dm = 1/sqrt(u (2 - u))."""\\n    md = m.detach().clamp(0.0, PI / 4)\\n    t = (3 * md).clamp_min(1e-300) ** (1 / 3)\\n    t = torch.minimum(t, torch.full_like(t, PI / 2))\\n    for _ in range(7):\\n        f = (2 * t - torch.sin(2 * t)) / 4 - md\\n        d = (1 - torch.cos(2 * t)) / 2\\n        t = (t - f / d.clamp_min(1e-30)).clamp(0.0, PI / 2)\\n    u0 = 1 - torch.cos(t)\\n    return u0 + (m - seg_area(u0)) / (u0 * (2 - u0)).clamp_min(1e-24).sqrt()\\n\\n\\ndef stadium_Minv2(m, E, rho, W, a):\\n    """same function as sw_pipe.stadium_Minv; the caps (seg_inv) are evaluated only on the points that are in a cap."""\\n    e = W * rho * PI / 4\\n    out = rho + (m - e) / W\\n    md, ed, ad = m.detach(), e.detach(), a.detach()\\n    iL = (md < ed).nonzero(as_tuple=True)[0]\\n    if iL.numel():\\n        out = out.index_put((iL,), rho * seg_inv2(m[iL] / (W[iL] * rho)))\\n    iR = (md > ad - ed).nonzero(as_tuple=True)[0]\\n    if iR.numel():\\n        out = out.index_put((iR,), E - rho * seg_inv2((a[iR] - m[iR]) / (W[iR] * rho)))\\n    return out\\n\\n\\ndef _b5w(t):\\n    """uniform quintic B-spline blending weights (sum to 1), C^4."""\\n    t2 = t * t; t3 = t2 * t; t4 = t3 * t; t5 = t4 * t\\n    return ((1 - t) ** 5 / 120,\\n            (5 * t5 - 20 * t4 + 20 * t3 + 20 * t2 - 50 * t + 26) / 120,\\n            (-10 * t5 + 30 * t4 - 60 * t2 + 66) / 120,\\n            (10 * t5 - 20 * t4 - 20 * t3 + 20 * t2 + 50 * t + 26) / 120,\\n            (-5 * t5 + 5 * t4 + 10 * t3 + 10 * t2 + 5 * t + 1) / 120,\\n            t5 / 120)\\n\\n\\nclass SWPipe2(SWPipe):\\n    X1MAX = 16.0          # bound for x1 in the strip chart during deoff / deoff2 (largest D + 2 (1 + DK) < 15)\\n\\n    def __init__(self, L, x0=4e-7, om_interp=\\\'bspline5\\\', om_ng=24001, compat13=False, nit_ra=12, nit_rb=30,\\n                 tol=1e-13, **kw):\\n        self._om_interp, self._om_ng, self.compat13 = om_interp, om_ng, compat13\\n        self.tol = tol\\n        super().__init__(L, **kw)\\n        self.nit_ra, self.nit_rb = nit_ra, nit_rb\\n        self.x0 = x0\\n        self.rho1 = math.sqrt(x0 / PI)\\n        # |x1 - xh1| <= pi s0 dp^2,  |dp| <= 1/2 + 1.01 pi s0 x1  (strip chart B_s0, |y1 - 1/2| <= 1/2)\\n        self.e_s0 = PI * self.s0 * (0.5 + 1.01 * PI * self.s0 * self.X1MAX) ** 2\\n        self._P6 = torch.tensor([self.it[n][\\\'p\\\'] for n in MIDDLE])\\n        self.margins = self.check_inequalities()\\n\\n    # ---------------------------------------------------------------- build-time inequalities\\n    def check_inequalities(self):\\n        L, tau, DK, e0 = self.L, self.tau, self.DK, self.e_s0\\n        m = {}\\n        m[\\\'slack = L - 1 - DK\\\'] = L - 1 - DK\\n        m[\\\'gap_bottom = 3.5 tau - DK  (W1 | W2 in s)\\\'] = 3.5 * tau - DK\\n        m[\\\'deoff2 switch width = 3.5 tau - DK - 1.1 e_s0\\\'] = 3.5 * tau - DK - 1.1 * e0\\n        m[\\\'deoff W8 | CX: 2 tau - 1.25 e_s0 - 2 tr\\\'] = 2 * tau - 1.25 * e0 - 2 * self._deoff_tr()\\n        m[\\\'deoff tr\\\'] = self._deoff_tr()\\n        m[\\\'Omega table: tau - 3 h\\\'] = (tau - 3 * self._Om[3]) if self._Om is not None else 1.0\\n        m[\\\'layout: min free angle - g_far\\\'] = self.min_free_angle - self.g_far\\n        m[\\\'layout: mfree0\\\'] = self.budget[\\\'mfree0\\\']\\n        # fibre margin: a_j(s) - (fibre bound of the ball image), relative to the bound, on the ball levels\\n        worst = 1e9\\n        for n in MIDDLE:\\n            it = self.it[n]; c = it[\\\'c\\\']\\n            T = torch.linspace(0.0, 1 + DK, 4001)\\n            a = self.a_item(n, it[\\\'P\\\'] + T)\\n            if c == 0:\\n                bd = 1 + DK - T\\n            elif c == 1:\\n                bd = T\\n            else:\\n                bd = torch.minimum(T / c, (1 + DK - T) / (1 - c))\\n            bd = bd.clamp(max=1.0)\\n            worst = min(worst, float((a - bd).min()))\\n        m[\\\'fibre margin min_s (a_j - bound)\\\'] = worst\\n        # far interval inside the sector plateau: wf/2 < 0.105\\n        s = torch.linspace(-7 / 6 * L, 7 / 6 * L, 20001)\\n        lay = self.layout(s)\\n        wfmax = max(float((lay[\\\'wfar\\\'][\\\'W2\\\'] + lay[\\\'wfar\\\'][\\\'W7\\\']).max()), float((lay[\\\'wfar\\\'][\\\'T3\\\'] + lay[\\\'wfar\\\'][\\\'T6\\\']).max()),\\n                    float(lay[\\\'wfar\\\'][\\\'T4\\\'].max()), float(lay[\\\'wfar\\\'][\\\'T5\\\'].max()))\\n        m[\\\'sector plateau 0.105 - wf/2\\\'] = 0.105 - wfmax / 2\\n        m[\\\'stadium: E - 2 rho_f (min)\\\'] = float((lay[\\\'E\\\'] - 2 * lay[\\\'rho_f\\\']).min())\\n        m[\\\'chart: x0 > 0\\\'] = self.x0\\n        bad = {k: v for k, v in m.items() if not (v > 0)}\\n        if bad:\\n            raise ValueError(\\\'SWPipe2: violated build-time inequalities (L = %r): %r\\\' % (L, bad))\\n        return m\\n\\n    def _deoff_tr(self):\\n        if self.compat13:\\n            return 0.25 * self.tau\\n        return min(0.25 * self.tau, (2 * self.tau - 1.25 * self.e_s0) / 2.2)\\n\\n    # ---------------------------------------------------------------- Omega (C^4 quintic B-spline of the node values)\\n    def _init_omega(self, ng=None):\\n        ng = ng or self._om_ng\\n        if self._om_interp == \\\'hermite\\\':\\n            return super()._init_omega(ng)\\n        smax0 = 7 / 6 * self.L + 3 * self.tau\\n        h = 2 * smax0 / (ng - 1)\\n        n2 = ng + 8\\n        smax = smax0 + 4 * h\\n        s = torch.linspace(-smax, smax, n2).requires_grad_(True)\\n        lay = self.layout(s.clamp(-smax0, smax0))\\n        num = torch.zeros(n2); den = torch.full((n2,), 1e-8)\\n        for n in MIDDLE:\\n            c = lay[\\\'phic\\\'][n]\\n            dc, = torch.autograd.grad(c.sum(), s, retain_graph=True)\\n            w = lay[\\\'W\\\'][n].detach() ** 2\\n            num = num + w * dc; den = den + w\\n        dOm = -(num / den).detach()\\n        sd = s.detach()\\n        Om = torch.cat([torch.zeros(1), torch.cumsum(0.5 * h * (dOm[1:] + dOm[:-1]), 0)])\\n        Om = Om - Om[n2 // 2]\\n        self._Om = (sd, Om, dOm, h, -smax)\\n\\n    def Omega(self, s):\\n        if self._om_interp == \\\'hermite\\\':\\n            return super().Omega(s)\\n        sg, Om, dOm, h, s0 = self._Om\\n        u = ((s - s0) / h).clamp(2.0, len(sg) - 4 - 1e-9)\\n        i = u.detach().floor().long()\\n        w = _b5w(u - i)\\n        out = w[0] * Om[i - 2]\\n        for j in range(1, 6):\\n            out = out + w[j] * Om[i - 2 + j]\\n        return out\\n\\n    # ---------------------------------------------------------------- layout (same formulas; also returns a_j)\\n    def layout(self, s):\\n        x_lo, x_hi = self.radial(s)\\n        E = x_hi - x_lo\\n        rho_f = self.rho_p * E / self.Ep\\n        ad = {n: self.a_item(n, s) for n in MIDDLE}\\n        den = E - KAP * rho_f\\n        Wd = {n: ad[n] / den for n in MIDDLE}\\n        sec = [Wd[\\\'W2\\\'] + Wd[\\\'W7\\\'], Wd[\\\'T3\\\'] + Wd[\\\'T6\\\'], Wd[\\\'T4\\\'], Wd[\\\'T5\\\']]\\n        fmin = self.f_min\\n        gaps = [self.gam * (sec[k] + sec[k + 1]) / 2 + fmin for k in range(3)]\\n        tot = sec[0] + sec[1] + sec[2] + sec[3] + gaps[0] + gaps[1] + gaps[2]\\n        cen, lo = [], -tot / 2\\n        for k in range(4):\\n            cen.append(lo + sec[k] / 2)\\n            lo = lo + sec[k] + (gaps[k] if k < 3 else 0.0)\\n        phif = {\\\'W2\\\': cen[0], \\\'W7\\\': cen[0], \\\'T3\\\': cen[1], \\\'T6\\\': cen[1], \\\'T4\\\': cen[2], \\\'T5\\\': cen[3]}\\n        if getattr(self, \\\'_Om\\\', None) is not None:\\n            Om = self.Omega(s)\\n            phif = {k: v + Om for k, v in phif.items()}\\n        r = E / self.Ep\\n        psi = {n: phif[n] * r for n in MIDDLE}\\n        delta = {n: psi[n] - self.it[n][\\\'alpha\\\'] for n in MIDDLE}\\n        wfar = {n: Wd[n] * r for n in MIDDLE}\\n        Xc = (x_lo - self.X_a * r) / (1 - r)\\n        return dict(E=E, x_lo=x_lo, x_hi=x_hi, rho_f=rho_f, W=Wd, a=ad, phic=phif, Sccw=tot / 2, Scw=tot / 2,\\n                    phi_ref=torch.zeros_like(s), psi=psi, delta=delta, wfar=wfar, r=r, Xc=Xc, lam=torch.log(1 / r),\\n                    sec=sec, cen=cen)\\n\\n    # ---------------------------------------------------------------- segments\\n    def seg_H(self, m, y, u):\\n        name = SEGS[m]\\n        if name not in (\\\'deoff\\\', \\\'deoff2\\\', \\\'Ra\\\', \\\'Rb\\\'):\\n            return super().seg_H(m, y, u)\\n        q1, q2, p1, p2 = y.unbind(1)\\n        S, dS = self.clk(u, m)\\n        tau, L, DK = self.tau, self.L, self.DK\\n        if name == \\\'deoff\\\':\\n            xh = self.xh1(q1)\\n            tr = self._deoff_tr()\\n            e = 1e-3 if self.compat13 else 1.25 * self.e_s0\\n            lo_mid = 0.0 if self.compat13 else 0.02\\n            H = 0\\n            for i, n in enumerate(BALLS):\\n                if n in (\\\'CY\\\', \\\'W1\\\'):\\n                    continue\\n                elif n == \\\'W8\\\':\\n                    Wi = band7(xh, self.P8 - 0.05, self.P8 + 1 + DK, tr)\\n                elif n == \\\'CX\\\':\\n                    Wi = band7(xh, self.K - e, self.K + 1 + DK, tr)\\n                else:\\n                    D, c = self.it[n][\\\'D\\\'], self.it[n][\\\'c\\\']\\n                    Wi = band7(xh, D - lo_mid, D + (1 + c) * (1 + DK), 0.05)\\n                H = H + self.v[i] * q1 * Wi\\n            return H\\n        if name == \\\'deoff2\\\':\\n            xh = self.xh1(q1)\\n            mu2 = q2 ** 2 + p2 ** 2\\n            sh = xh - mu2\\n            tr = 0.25 * tau\\n            g = 3.5 * tau - DK - (8e-4 if self.compat13 else 1.1 * self.e_s0)\\n            a0 = -7 / 6 * L - 1.5 * tau + DK + 0.05 * g\\n            sw = 1 - S7((sh - a0) / (0.9 * g))\\n            H = 0\\n            for i, n in ((0, \\\'CY\\\'), (1, \\\'W1\\\')):\\n                if n == \\\'CY\\\':\\n                    Wi = band7(xh, -0.05, 1 + DK, 0.02) * band7(mu2, self.K, self.K + 1 + DK, tr)\\n                else:\\n                    Wi = band7(xh, -0.05, 1 + DK, 0.02) * band7(mu2, self.Ptop - 1 - DK, self.Ptop, tr)\\n                H = H + self.v[i] * q1 * Wi * sw\\n            return H\\n        # ---------------- S-invariant reduced stages: H = pi chi_s(s) H_red(s, x, phi)\\n        s, x, phi = self.reduced_coords(y)\\n        gb = 3.5 * tau - DK\\n        lo, hi = -7 / 6 * L + 2 * tau - 0.05 * gb, 7 / 6 * L - 1.5 * tau + 0.05 * 3.5 * tau\\n        ltr, htr = 0.85 * gb, 0.85 * 3.5 * tau\\n        chis = (1 - S7((lo - s) / ltr)) * (1 - S7((s - hi) / htr))\\n        ii = (chis.detach() > 0).nonzero(as_tuple=True)[0]\\n        if ii.numel() == 0:\\n            return 0.0 * q1\\n        # the clamps are inactive on the support of chis (|s| < 7/6 L + 1.65 tau there) and for 1e-9 < x < 60\\n        smax = 7 / 6 * L + 2 * tau\\n        ss = s[ii].clamp(-smax, smax)\\n        xx = x[ii].clamp(1e-9, 60.0)\\n        Hr = self.Ra_H2(ss, xx, phi[ii], float(S)) if name == \\\'Ra\\\' else self.Rb_H2(ss, xx, phi[ii], float(S))\\n        return torch.zeros_like(s).index_put((ii,), PI * chis[ii] * Hr)\\n\\n    # ---- Ra: sector lift, all items in one solve\\n    def Ra_H2(self, s, x, phi, tau):\\n        lay = self.layout(s)\\n        with torch.no_grad():\\n            k = torch.floor((phi + 0.5) * 4).clamp(0, 3).long()            # sector 0..3, centres (k - 1.5)/4\\n            neg = s < 0\\n            j = torch.where(k == 0, torch.where(neg, 0, 5), torch.where(k == 1, torch.where(neg, 1, 4), k))\\n        dph = phi - (k.to(phi.dtype) - 1.5) / 4\\n        chi = win7(dph, 0.105, 0.015)\\n        T = s - self._P6[j]\\n        tq, sig = self.tau, self.sig\\n        right = sig + 1 + self.DK\\n        lv = S7((T - (sig - tq / 2)) / (tq / 2)) * (1 - S7((T - right) / (tq / 2)))\\n        ii = ((chi.detach() > 0) & (lv.detach() > 0)).nonzero(as_tuple=True)[0]\\n        H = torch.zeros_like(s)\\n        if ii.numel() == 0:\\n            return H + 0.0 * (s + x + phi)\\n        ji = j[ii].unsqueeze(1)\\n        a = torch.stack([lay[\\\'a\\\'][n] for n in MIDDLE], 1)[ii].gather(1, ji).squeeze(1).clamp_min(1e-12)\\n        Wf = torch.stack([lay[\\\'wfar\\\'][n] for n in MIDDLE], 1)[ii].gather(1, ji).squeeze(1)\\n        V = self._Ra_V2(x[ii], a, Wf, tau)\\n        return H.index_put((ii,), dph[ii] * V * chi[ii] * lv[ii]) + 0.0 * (s + x + phi)\\n\\n    def _Ra_Zd(self, x0, a, Wf):\\n        """detached radial endpoint map Z(x0) and its derivative Z\\\' = 2 h / w_t."""\\n        Cx = lens_C(x0, a, self.R_W)\\n        Zs = stadium_Minv2(Cx, self.Ep, self.rho_p, Wf, a)\\n        wt = stadium_w(Zs, self.Ep, self.rho_p, Wf).clamp_min(1e-12)\\n        return self.X_a + Zs, 2 * blob_h(x0, a, self.R_W) / wt\\n\\n    def _Ra_V2(self, x, a, Wf, tau):\\n        R, Xa, Ep = self.R_W, self.X_a, self.Ep\\n        with torch.no_grad():\\n            xd, ad, Wd = x.detach(), a.detach(), Wf.detach()\\n            sq = ad.sqrt()\\n            lo, hi = (R - sq) ** 2, (R + sq) ** 2\\n            glo, ghi = (1 - tau) * lo + tau * Xa, (1 - tau) * hi + tau * (Xa + Ep)\\n            x0 = lo + (hi - lo) * ((xd - glo) / (ghi - glo)).clamp(0.0, 1.0)\\n            blo, bhi = lo.clone(), hi.clone()\\n            tolv = self.tol * (1 + xd.abs())\\n            for it in range(self.nit_ra):\\n                Z, Zp = self._Ra_Zd(x0, ad, Wd)\\n                f = (1 - tau) * x0 + tau * Z - xd\\n                blo = torch.where(f < 0, x0, blo); bhi = torch.where(f > 0, x0, bhi)\\n                x1 = x0 - f / ((1 - tau) + tau * Zp).clamp_min(1e-12)\\n                ok = (x1 > blo) & (x1 < bhi) & torch.isfinite(x1)\\n                x0 = torch.where(f.abs() <= tolv, x0, torch.where(ok, x1, 0.5 * (blo + bhi)))\\n            # guaranteed tail: g(x0) = (1 - tau) x0 + tau Z(x0) is continuous and strictly increasing on [lo, hi],\\n            # [blo, bhi] brackets the root (or x is outside [g(lo), g(hi)] and the root is clamped to an end).\\n            Z, Zp = self._Ra_Zd(x0, ad, Wd)\\n            f = (1 - tau) * x0 + tau * Z - xd\\n            bad = ((f.abs() > tolv) | ~torch.isfinite(f)).nonzero(as_tuple=True)[0]\\n            if bad.numel():\\n                lo_, hi_, xb, ab, Wb = blo[bad], bhi[bad], xd[bad], ad[bad], Wd[bad]\\n                for _ in range(60):\\n                    mid = 0.5 * (lo_ + hi_)\\n                    fm = (1 - tau) * mid + tau * self._Ra_Zd(mid, ab, Wb)[0] - xb\\n                    up = fm < 0\\n                    lo_ = torch.where(up, mid, lo_); hi_ = torch.where(up, hi_, mid)\\n                x0 = x0.index_put((bad,), 0.5 * (lo_ + hi_))\\n                Z, Zp = self._Ra_Zd(x0, ad, Wd)\\n        # one implicit-function step carrying the gradient (x0 detached; a, Wf, x carry the graph)\\n        Z0 = Xa + stadium_Minv2(lens_C(x0, a, R), Ep, self.rho_p, Wf, a)\\n        f = (1 - tau) * x0 + tau * Z0 - x\\n        dlt = -f / ((1 - tau) + tau * Zp).clamp_min(1e-12)\\n        return Z0 + (Zp - 1) * dlt - x0\\n\\n    # ---- Rb: closed-form inverse on the item intervals, safeguarded Newton + bisection elsewhere\\n    def Rb_H2(self, s, x, phi, tau):\\n        cm = self.circle_map(s)\\n        Xc = cm[\\\'lay\\\'][\\\'Xc\\\']\\n        with torch.no_grad():\\n            cmd = dict(cm)\\n            cmd[\\\'gaps\\\'] = [{kk: (vv.detach() if torch.is_tensor(vv) else vv) for kk, vv in g.items()} for g in cm[\\\'gaps\\\']]\\n            cmd[\\\'Ilo\\\'] = [v.detach() for v in cm[\\\'Ilo\\\']]\\n            cmd[\\\'Flo\\\'] = [v.detach() for v in cm[\\\'Flo\\\']]\\n            cmd[\\\'r\\\'] = cm[\\\'r\\\'].detach()\\n            r = cmd[\\\'r\\\']\\n            b, e = [], []\\n            for k in range(4):\\n                g = cmd[\\\'gaps\\\'][k]\\n                Il, Ih = cmd[\\\'Ilo\\\'][k], g[\\\'lo\\\']\\n                Fl = cmd[\\\'Flo\\\'][k]\\n                b += [Il, Ih]\\n                e += [(1 - tau) * Il + tau * Fl, (1 - tau) * Ih + tau * (Fl + (Ih - Il) / r)]\\n            b.append(b[0] + 1.0); e.append(e[0] + 1.0)\\n            B = torch.stack(b, 1); Ev = torch.stack(e, 1)\\n            target = Ev[:, 0] + torch.remainder(phi.detach() - Ev[:, 0], 1.0)\\n            p = (target.unsqueeze(1) >= Ev[:, 1:8]).sum(1, keepdim=True)\\n            lo_b, hi_b = B.gather(1, p).squeeze(1), B.gather(1, p + 1).squeeze(1)\\n            lo_e, hi_e = Ev.gather(1, p).squeeze(1), Ev.gather(1, p + 1).squeeze(1)\\n            p0 = lo_b + (target - lo_e) * (hi_b - lo_b) / (hi_e - lo_e).clamp_min(1e-300)\\n            p0 = torch.minimum(torch.maximum(p0, lo_b), hi_b)\\n            v, rh = self.Phi_f(cmd, p0)\\n            f = (1 - tau) * p0 + tau * v - target\\n            bad = ((f.abs() > self.tol) | ~torch.isfinite(f)).nonzero(as_tuple=True)[0]\\n            if bad.numel():\\n                # gap points (never on exact trajectories of the balls): safeguarded Newton, then bisection; the map\\n                # p -> (1 - tau) p + tau Phi(p) is strictly increasing and [lo_b, hi_b] brackets the root.\\n                cms = self._sub_cm(cmd, bad)\\n                lo_, hi_, tg, pb = lo_b[bad], hi_b[bad], target[bad], p0[bad]\\n                for _ in range(self.nit_rb):\\n                    vb, rb = self.Phi_f(cms, pb)\\n                    fb = (1 - tau) * pb + tau * vb - tg\\n                    lo_ = torch.where(fb < 0, pb, lo_); hi_ = torch.where(fb > 0, pb, hi_)\\n                    p1 = pb - fb / ((1 - tau) + tau * rb)\\n                    ok = (p1 > lo_) & (p1 < hi_) & torch.isfinite(p1)\\n                    pb = torch.where(fb.abs() <= self.tol, pb, torch.where(ok, p1, 0.5 * (lo_ + hi_)))\\n                vb, rb = self.Phi_f(cms, pb)\\n                fb = (1 - tau) * pb + tau * vb - tg\\n                b2 = ((fb.abs() > self.tol) | ~torch.isfinite(fb)).nonzero(as_tuple=True)[0]\\n                if b2.numel():\\n                    cm2 = self._sub_cm(cms, b2)\\n                    l2, h2, t2 = lo_[b2], hi_[b2], tg[b2]\\n                    for _ in range(60):\\n                        mid = 0.5 * (l2 + h2)\\n                        fm = (1 - tau) * mid + tau * self.Phi_f(cm2, mid)[0] - t2\\n                        up = fm < 0\\n                        l2 = torch.where(up, mid, l2); h2 = torch.where(up, h2, mid)\\n                    pb = pb.index_put((b2,), 0.5 * (l2 + h2))\\n                p0 = p0.index_put((bad,), pb)\\n            tgt0 = target\\n        # one implicit-function step carrying the gradient (p0 detached; s through cm, phi through the target)\\n        v0, rh0 = self.Phi_f(cm, p0)\\n        rh0 = rh0.detach()\\n        f = (1 - tau) * p0 + tau * v0 - (phi + (tgt0 - phi.detach()))\\n        dlt = -f / ((1 - tau) + tau * rh0)\\n        G = -(v0 + (rh0 - 1) * dlt - p0)\\n        return (x - Xc) * G\\n\'\n\nimport math\n\nETA = 0.10\nKD = 0.25\nKS = 0.065\nKR = 1.4\nSTEPS13 = dict(kick=24, kh1=64, kh2=24, unwrap=64, strip=96, move=64, deoff=24, trans=48, unD=64, deoff2=24, wrap=96,\n               Ra=220, Rb=420)\nCLOCKS = dict(kick=\'sin4\', kh1=\'sin4\', kh2=\'sin4\', unwrap=\'sstep\', strip=\'sin4\', move=\'sin4\', deoff=\'sin4\',\n              trans=\'sin4\', unD=\'sin4\', deoff2=\'sin4\', wrap=\'sstep\', Ra=\'sin4\', Rb=\'exp\')\n\n\ndef sw2_steps(dl, mult=None):\n    """per-segment step numbers.  STEP LAW: front-end segments scale like\n    (0.05/dl)^(1/4) (accuracy only), reduced stages like (0.05/dl)^P_RED."""\n    f = max(1.0, 0.05 / dl)\n    m = dict(mult or {})\n    out = {}\n    for k, v in STEPS13.items():\n        if k in (\'Ra\', \'Rb\'):\n            g = f ** P_RED\n        elif k in (\'unwrap\', \'wrap\', \'kh1\'):\n            g = f ** P_WRAP\n        else:\n            g = f ** P_FRONT\n        out[k] = int(math.ceil(v * g * m.get(k, 1.0) * m.get(\'all\', 1.0) / 4.0) * 4)\n    return out\n\n\nP_RED = 0.5\nP_WRAP = 0.5\nP_FRONT = 0.25\n\n\ndef sw2_params(eps, mult=None):\n    eps = float(eps)\n    Rn = (10.0 / (1.0 - eps)) ** 0.25\n    dmax = 6.0 / 19.0 * Rn * Rn - 1.0\n    dl = min(0.05, (1.0 - ETA) * dmax)\n    if not dl > 0:\n        raise ValueError(\'eps is at or below the static floor 1/361 of the A = 19/6 configuration\')\n    L = 1.0 + dl\n    d = min(0.004, KD * dl)\n    DK = 1.025 * d\n    kh = (d, 9.0 + math.log(0.004 / d), d / 40.0, 1.618 * math.sqrt(0.75 * d / math.pi), 0.75 * d)\n    x0 = 4e-7 * (d / 0.004) ** 3\n    s0 = min(1e-3, KS * dl)\n    rho_p = min(0.03, KR * dl)\n    tau = (dl - DK) / 3.5\n    e_s0 = math.pi * s0 * (0.5 + 1.01 * math.pi * s0 * 16.0) ** 2\n    steps = sw2_steps(dl, mult)\n    ineq = {\'slack\': dl - DK, \'gap_bottom\': 3.5 * tau - DK, \'deoff2_switch\': 3.5 * tau - DK - 1.1 * e_s0,\n            \'deoff_W8_CX\': 1.5 * tau - 1.25 * e_s0, \'R_margin\': Rn - math.sqrt(19.0 / 6.0 * L)}\n    bad = {k: v for k, v in ineq.items() if not v > 0}\n    if bad:\n        raise ValueError(\'sw2_params(%r): violated inequalities %r\' % (eps, bad))\n    kw = dict(DK=DK, kh=kh, s0=s0, x0=x0, rho_p=rho_p, comp=\'omega\', gfar_frac=0.0, gam_frac=0.45, fmin_frac=0.12,\n              gc_frac=0.15, bump_m=0.1, bump_t=0.7, chis_wide=True, lam_clk=3.0, beta_clk=0.1, clocks=dict(CLOCKS),\n              weights=steps, om_ng=int(min(200001, max(24001, round(2.4 / (tau / 6.0)) + 1))))\n    return dict(eps=eps, L=L, dl=dl, R_need=Rn, R_slot=math.sqrt(19.0 / 6.0 * L), d=d, tau=tau, e_s0=e_s0, kw=kw,\n                steps=steps, N1=sum(steps.values()), ineq=ineq)\n\n\nEPS_MIN = 0.005\n\n\ndef recommended_steps(epsilon, safety=1):\n    """Number of fixed RK4 steps over [0, 1] for this epsilon: safety * N1, N1 = sum of the per-segment step\n    numbers of sw2_params (every segment then holds an integer number of steps; use integer multiples of N1 only).\n    N1 is the smallest step count at which the local verifier was run and passed (also at 2 N1).\n    At N1 the worst sample points (levels where a tent peak meets a foot) still carry\n    an RK4 error of 1e-4 .. 1e-3 in reduced coordinates, which is of the order of the radius margin; safety = 2\n    brings it below the window margins (measured at epsilon = 0.02 and 0.01).  For epsilon not in that table the\n    value follows the same step law and is a prediction, not a measurement."""\n    return int(safety) * sw2_params(min(max(float(epsilon), EPS_MIN), 0.999999))[\'N1\']\n\n\ndef _module_source(p):\n    import json\n    kw = json.dumps(p[\'kw\'])\n    tail = (\n        "\\n\\nimport json as _json\\n"\n        "_KW = _json.loads(" + repr(kw) + ")\\n"\n        "_old = torch.get_default_dtype()\\n"\n        "torch.set_default_dtype(torch.float64)\\n"\n        "try:\\n"\n        "    _T = SWPipe2(" + repr(p[\'L\']) + ", **_KW)\\n"\n        "finally:\\n"\n        "    torch.set_default_dtype(_old)\\n"\n        "\\n\\n"\n        "def Hamiltonian(Q, P, t):\\n"\n        "    return _T.H(Q, P, t)\\n")\n    return SRC + tail\n\n\ndef solution(k, epsilon, check=True):\n    if isinstance(k, bool) or int(k) != k or k < 10 or not (0 < float(epsilon) < 1):\n        raise ValueError(\'require integer k >= 10 and 0 < epsilon < 1\')\n    if int(k) != 10:\n        raise NotImplementedError(\'solution_k10_sw2 handles k = 10 only\')\n    eps = float(epsilon)\n    if eps < EPS_MIN:\n        raise NotImplementedError(\'solution_k10_sw2: reach is epsilon >= %r for k = 10 (local verifier passes at N \'\n                                  \'and 2N down to that value; static floor of the A = 19/6 sheared-window \'\n                                  \'configuration: 1/361 = 0.00277; below EPS_MIN nothing was run)\' % EPS_MIN)\n    p = sw2_params(eps)\n    src = _module_source(p)\n    if check:\n        # build-time inequalities (SWPipe2.check_inequalities) are evaluated when the module is executed\n        try:\n            exec(compile(src, \'<solution_k10_sw2 build check>\', \'exec\'), {\'__name__\': \'sw2_build_check\'})\n        except ValueError as ex:\n            raise NotImplementedError(\'solution_k10_sw2: parameter inequalities violated at epsilon = %r: %s\'\n                                      % (eps, ex))\n    return src\n'}
EXT_META = [{'name': 'k10_sw2', 'ks': (10,), 'eps_lo': 0.005, 'closed': True, 'steps': None, 'safety': 2, 'evidence': 'numerical: fixed-step RK4 passes at N = recommended_steps and 2N (see README.md)'}]
CLK_TORIC = ('sin4', 'sin4', 'sin4', 'sstep', 'sstep', 'sin4', 'sin4', 'sstep')
# FastToric presets: weights in percent of unit time (integer steps per segment
# whenever N is a multiple of 100)
FAST8 = dict(weights=(10, 10, 11, 4, 13, 13, 7, 10, 22),            # early-slide order, 9 segments
             clock=('sin16', 'sin16', 'sin4', 'sin4', 'sstep', 'sstep', 'sin8', 'sin16', 'sin4'),
             s4split=None, order='early')
FAST9 = dict(weights=(8, 11, 4, 13, 11, 20, 11, 8, 14),             # sheared layouts, classic order
             clock=('sin8', 'sin4', 'sin4', 'sstep', 'sstep', 'sstep', 'sin8', 'sin8', 'sstep'),
             s4split=('conc', 'sstep', 'sin8'), order='classic')
_NS = {}
_ORI = {'0': (1, 1), '1': (-1, -1), '2': (1, -1), '3': (-1, 1)}


def _P():
    if not _NS:
        exec(compile(PLAN_SRC, '<plan>', 'exec'), _NS)
    return _NS


def _check(k, epsilon):
    if isinstance(k, bool) or int(k) != k or k < 10 or not (0 < float(epsilon) < 1):
        raise ValueError('require integer k >= 10 and 0 < epsilon < 1')
    return int(k), float(epsilon)


# ---------------------------------------------------------------- family 'toric'
def _toric_plan(k, epsilon):
    return _P()['plan'](k, epsilon, LIB, _maxhead(k))


def _maxhead(k):
    """MAXHEAD in the planner's format for this k: [(extent numerator, m, count)], extent of the innermost k pieces."""
    out = []
    for m, brk in MAXHEAD:
        e, tot = None, brk[-1][0]
        for cnt, ext in brk:
            if cnt >= k:
                e = ext
                break
        out.append((e if e is not None else 10 ** 9, m, tot))
    return out


def _toric_reach(k):
    P = _P()
    if k > P['K_MAX']:
        return None
    return min(P['reach'](k, LIB, _maxhead(k)).values())


def _toric_source(k, epsilon):
    fam, par, dens, steps = _toric_plan(k, epsilon)
    n, m = par['n'], par['m']
    common = (f"g0={par['g0']!r}, kh={par['kh']!r}, kh_out={par['kh_out']!r}, s0={par['s0']!r}, x0={par['x0']!r}")
    if fam == 'square':
        inst = f"_T = Toric({n}, {common}, clock={CLK_TORIC!r})"
    elif fam == 'subset':
        inst = f"_T = ToricSubset({k}, {n}, {common}, v0={-4.4 * (k - 1) / 2!r}, clock={CLK_TORIC!r})"
    elif fam == 'sublayout':
        blob = MAXBLOB[par['payload']][:3 * k]
        lay = [((float(ord(blob[3 * j]) - 33) / m, float(ord(blob[3 * j + 1]) - 33) / m), _ORI[blob[3 * j + 2]])
               for j in range(k)]
        inst = (f"_T = ToricGeneral({k}, {lay!r}, list(range({k})), A={n / m!r}, {common}, "
                f"v0={-4.4 * (k - 1) / 2!r}, q1_cut=1e9, clock={CLK_TORIC!r})")
    elif par['sheared'] == 0:
        lay = [((c1 / m, c2 / m), (s1, s2)) for (c1, c2, s1, kk, s2) in par['payload']]
        inst = (f"_T = ToricGeneral({k}, {lay!r}, list(range({k})), A={n / m!r}, {common}, "
                f"v0={-4.4 * (k - 1) / 2!r}, q1_cut=1e9, clock={CLK_TORIC!r})")
    else:
        pcs = [((c1 / m, c2 / m), ((s1, kk), (0, s2))) for (c1, c2, s1, kk, s2) in par['payload']]
        inst = f"_T = ToricGeneric({k}, {pcs!r}, A={n / m!r}, {common})"
    fast = FAST9 if par['sheared'] else FAST8
    inst += (f"\n_F = FastToric(_T, weights={fast['weights']!r}, clock={fast['clock']!r}, "
             f"s4split={fast['s4split']!r}, order={fast['order']!r})")
    head = (f"\n\n# ---- instance: family toric/{fam}, k={k}, epsilon={epsilon!r}, A={n}/{m}, regime {par['regime']}, "
            f"density bound {dens:.6f}, recommended RK4 steps {steps}\n")
    return SRC + head + inst + '\n\n\ndef Hamiltonian(Q, P, t):\n    return _F.H(Q, P, t)\n'


def _toric_describe(k, epsilon):
    fam, par, dens, steps = _toric_plan(k, epsilon)
    return dict(family='toric', kind=fam, A='%d/%d' % (par['n'], par['m']), sheared=par['sheared'],
                regime=par['regime'], u=par['u'], g0=par['g0'], d_eff=par['kh_out'][0], s0=par['s0'],
                density_bound=dens, steps=steps)


# ---------------------------------------------------------------- registry
FAMILIES = []


def register(name, reach, source, steps, closed=False, evidence='', describe=None):
    """reach(k) -> infimum of the covered epsilon for this k (None: k not covered); closed: epsilon = reach(k) is
    itself covered; source(k, epsilon) -> module source; steps(k, epsilon) -> recommended RK4 steps."""
    FAMILIES.append(dict(name=name, reach=reach, source=source, steps=steps, closed=closed, evidence=evidence,
                         describe=describe))


def _ext_ns(name):
    if ('ext', name) not in _NS:
        ns = {'__name__': 'ext_' + name}
        exec(compile(EXT_SRC[name], '<' + name + '>', 'exec'), ns)
        _NS[('ext', name)] = ns
    return _NS[('ext', name)]


def _ext_solution(name):
    return _ext_ns(name)['solution']


def _ext_steps(e, epsilon):
    # constant step count from the registration, or the embedded file's own recommended_steps(epsilon)
    if e.get('steps'):
        return e['steps']
    rs = _ext_ns(e['name'])['recommended_steps']
    return rs(epsilon, e['safety']) if e.get('safety') else rs(epsilon)


register('toric', _toric_reach, _toric_source, lambda k, e: _toric_plan(k, e)[3],
         evidence='exact flow packs [derived]; RK4 pass at N and 2N [numerical, sampled grid]',
         describe=_toric_describe)
for _e in EXT_META:
    register(_e['name'], (lambda k, _e=_e: _e['eps_lo'] if k in _e['ks'] else None),
             (lambda k, e, _e=_e: _ext_solution(_e['name'])(k, e)), (lambda k, e, _e=_e: _ext_steps(_e, e)),
             closed=_e.get('closed', False), evidence=_e.get('evidence', ''))


def _covers(f, k, epsilon):
    r = f['reach'](k)
    return r is not None and (epsilon > r or (f['closed'] and epsilon >= r))


def coverage(k):
    """{family name: smallest covered epsilon (infimum)} for this k."""
    k, _ = _check(k, 0.5)
    return {f['name']: f['reach'](k) for f in FAMILIES if f['reach'](k) is not None}


def eps_min(k):
    """infimum of the epsilon covered for this k (None: k not covered at all)."""
    c = coverage(k)
    return min(c.values()) if c else None


def _choose(k, epsilon):
    k, epsilon = _check(k, epsilon)
    cand = [f for f in FAMILIES if _covers(f, k, epsilon)]
    if not cand:
        c = coverage(k)
        if not c:
            raise NotImplementedError(f'(k={k}, epsilon={epsilon}) not covered: no family handles k = {k} '
                                      f'(lattice-toric families: k <= {_P()["K_MAX"]})')
        raise NotImplementedError(f'(k={k}, epsilon={epsilon}) not covered; reach for k = {k}: epsilon > '
                                  f'{min(c.values()):.4f} (' + ', '.join(f'{n}: {v:.4f}' for n, v in c.items()) + ')')
    return min(cand, key=lambda f: f['steps'](k, epsilon)), k, epsilon


def recommended_steps(k, epsilon):
    """RK4 step count N at which the flow of solution(k, epsilon) is expected to pack (and at 2N)."""
    f, k, epsilon = _choose(k, epsilon)
    return f['steps'](k, epsilon)


def describe(k, epsilon):
    f, k, epsilon = _choose(k, epsilon)
    d = f['describe'](k, epsilon) if f['describe'] else dict(family=f['name'], steps=f['steps'](k, epsilon))
    d['evidence'] = f['evidence']
    return d


def solution(k, epsilon):
    f, k, epsilon = _choose(k, epsilon)
    return f['source'](k, epsilon)
